  grid-template-columns: 1.7fr 1fr 1fr 1fr;
  gap: 20px;
  align-items: stretch;
}
.vtj-coding-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.25s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.25s ease;
  position: relative;
}
html.dark .vtj-coding-card {
  background: #111827;
  border-color: #1E293B;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}
.vtj-coding-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.07);
  border-color: #CBD5E1;
}
html.dark .vtj-coding-card:hover {
  border-color: #334155;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.35);
}
.vtj-coding-img-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 10px;
  overflow: hidden;
  background: #0F172A;
  margin-bottom: 1.15rem;
}
.vtj-coding-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.vtj-coding-card:hover .vtj-coding-img {
  transform: scale(1.025);
}
.vtj-coding-body {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.vtj-coding-card-title {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  color: #0F172A;
  line-height: 1.36;
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
  transition: color 0.2s ease;
}
html.dark .vtj-coding-card-title {
  color: #F8FAFC;
}
.vtj-coding-card:hover .vtj-coding-card-title {
  color: #2563EB;
}
html.dark .vtj-coding-card:hover .vtj-coding-card-title {
  color: #60A5FA;
}
.vtj-coding-card-featured .vtj-coding-card-title {
  font-size: 1.25rem;
}
.vtj-coding-card-desc {
  font-size: 0.84rem;
  color: #64748B;
  line-height: 1.48;
  margin: 0 0 0.75rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
html.dark .vtj-coding-card-desc {
  color: #94A3B8;
}
.vtj-coding-card-meta {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.78rem;
  color: #64748B;
  margin-top: auto;
  padding-top: 0.5rem;
}
html.dark .vtj-coding-card-meta {
  color: #94A3B8;
}

/* Responsive Media Queries for Category Sections */
@media (max-width: 1200px) {
  .vtj-coding-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
  }
}
@media (max-width: 992px) {
  .vtj-ai-grid {
    flex-direction: column;
    gap: 24px;
  }
  .vtj-cat-container {
    padding: 0 1.5rem;
  }
}
@media (max-width: 768px) {
  .vtj-cat-section {
    padding: 2.25rem 0 2.75rem;
  }
  .vtj-cat-container {
    padding: 0 1rem;
  }
  .vtj-ai-featured {
    padding: 0;
    border-radius: 12px;
    overflow: hidden;
  }
  .vtj-ai-featured-img-wrap {
    border-radius: 12px 12px 0 0;
    margin-bottom: 0;
  }
  .vtj-ai-featured-body {
    padding: 14px 16px 16px;
  }
  .vtj-ai-secondary-card {
    flex-direction: column;
    padding: 0;
    border-radius: 12px;
    overflow: hidden;
    gap: 0;
  }
  .vtj-ai-secondary-img-wrap {
    width: 100%;
    aspect-ratio: 16 / 9;
    border-radius: 12px 12px 0 0;
  }
  .vtj-ai-secondary-body {
    width: 100%;
    padding: 14px 16px 16px;
    box-sizing: border-box;
  }
  .vtj-coding-grid {
    grid-template-columns: 1fr;
    gap: 18px;
  }
  .vtj-coding-card {
    padding: 0;
    border-radius: 12px;
    overflow: hidden;
  }
  .vtj-coding-img-wrap {
    border-radius: 12px 12px 0 0;
    margin-bottom: 0;
  }
  .vtj-coding-body {
    padding: 14px 16px 16px;
  }
}

/* ============================================================
   8D. VTJ HOMEPAGE: DEVELOPER TOOLS & SOFTWARE + MUST READ
============================================================ */
/* Section 1: Developer Tools Layout */
.vtj-devtools-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 24px;
  align-items: start;
}
.vtj-devtools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.vtj-devtool-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.03);
  transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.22s ease, border-color 0.22s ease;
  text-decoration: none;
  color: inherit;
  position: relative;
}
html.dark .vtj-devtool-card {
  background: #111827;
  border-color: #1E293B;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}
.vtj-devtool-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.07);
  border-color: #CBD5E1;
}
html.dark .vtj-devtool-card:hover {
  border-color: #334155;
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.35);
}
.vtj-devtool-img-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  border-radius: 8px;
  overflow: hidden;
  background: #0F172A;
  margin-bottom: 0.75rem;
}
.vtj-devtool-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.35s ease;
}
.vtj-devtool-card:hover .vtj-devtool-img {
  transform: scale(1.03);
}
.vtj-devtool-icon-badge {
  position: absolute;
  bottom: 8px;
  left: 8px;
  z-index: 2;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35);
}
.vtj-icon-purple { background: #7C3AED; }
.vtj-icon-blue { background: #2563EB; }
.vtj-icon-green { background: #059669; }
.vtj-icon-orange { background: #EA580C; }
.vtj-icon-indigo { background: #6366F1; }

.vtj-devtool-body {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.vtj-devtool-badge {
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  padding: 2px 6px;
  border-radius: 4px;
  display: inline-flex;
  align-self: flex-start;
  margin-bottom: 0.45rem;
  line-height: 1.2;
}
.vtj-devtool-title {
  font-family: var(--font-heading);
  font-size: 0.96rem;
  font-weight: 700;
  color: #0F172A;
  line-height: 1.35;
  margin: 0 0 0.4rem;
  letter-spacing: -0.01em;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: color 0.2s ease;
}
html.dark .vtj-devtool-title {
  color: #F8FAFC;
}
.vtj-devtool-card:hover .vtj-devtool-title {
  color: #2563EB;
}
html.dark .vtj-devtool-card:hover .vtj-devtool-title {
  color: #60A5FA;
}
.vtj-devtool-excerpt {
  font-size: 0.78rem;
  color: #64748B;
  line-height: 1.45;
  margin: 0 0 0.6rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
html.dark .vtj-devtool-excerpt {
  color: #94A3B8;
}
.vtj-devtool-meta {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.72rem;
  color: #94A3B8;
  margin-top: auto;
  padding-top: 0.4rem;
}

/* Editor's Pick Sidebar */
.vtj-editors-pick-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 18px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
html.dark .vtj-editors-pick-card {
  background: #111827;
  border-color: #1E293B;
}
.vtj-sidebar-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid #F1F5F9;
}
html.dark .vtj-sidebar-head {
  border-bottom-color: #1E293B;
}
.vtj-sidebar-head-title {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  color: #0F172A;
  margin: 0;
}
html.dark .vtj-sidebar-head-title {
  color: #F8FAFC;
}
.vtj-sidebar-head-link {
  font-size: 0.82rem;
  font-weight: 600;
  color: #2563EB;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  transition: gap 0.2s ease, color 0.2s ease;
}
.vtj-sidebar-head-link:hover {
  color: #1D4ED8;
  gap: 5px;
}
.vtj-editors-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.vtj-editors-item {
  display: flex;
  gap: 12px;
  align-items: center;
  text-decoration: none;
  color: inherit;
  padding-bottom: 14px;
  border-bottom: 1px solid #F1F5F9;
  transition: transform 0.2s ease;
}
html.dark .vtj-editors-item {
  border-bottom-color: #1E293B;
}
.vtj-editors-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.vtj-editors-item:hover {
  transform: translateX(3px);
}
.vtj-editors-img-wrap {
  width: 72px;
  height: 64px;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
  background: #0F172A;
}
.vtj-editors-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.vtj-editors-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.vtj-editors-badge {
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 1px 5px;
  border-radius: 3px;
  align-self: flex-start;
  margin-bottom: 3px;
}
.vtj-editors-title {
  font-family: var(--font-heading);
  font-size: 0.88rem;
  font-weight: 700;
  color: #0F172A;
  line-height: 1.3;
  margin: 0 0 4px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: color 0.2s ease;
}
html.dark .vtj-editors-title {
  color: #F8FAFC;
}
.vtj-editors-item:hover .vtj-editors-title {
  color: #2563EB;
}
.vtj-editors-meta {
  font-size: 0.72rem;
  color: #94A3B8;
}

/* ------------------------------------------------------------
   Section 2: Must Read Layout
------------------------------------------------------------ */
.vtj-mustread-layout {
  display: grid;
  grid-template-columns: 1.5fr 1fr 0.9fr;
  gap: 24px;
  align-items: stretch;
}
.vtj-mustread-featured {
  position: relative;
  border-radius: 14px;
  overflow: hidden;
  background: #0F172A;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 26px;
  text-decoration: none;
  color: #FFFFFF;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.25s ease;
}
.vtj-mustread-featured:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.16);
}
.vtj-mustread-bg-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 1;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.vtj-mustread-featured:hover .vtj-mustread-bg-img {
  transform: scale(1.03);
}
.vtj-mustread-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.15) 0%, rgba(15, 23, 42, 0.6) 48%, rgba(15, 23, 42, 0.95) 100%);
  z-index: 2;
}
.vtj-mustread-featured-badge {
  position: absolute;
  top: 20px;
  left: 20px;
  z-index: 3;
  background: #6366F1;
  color: #FFFFFF;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 4px 10px;
  border-radius: 6px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}
.vtj-mustread-featured-content {
  position: relative;
  z-index: 3;
}
.vtj-mustread-featured-title {
  font-family: var(--font-heading);
  font-size: 1.55rem;
  font-weight: 700;
  color: #FFFFFF;
  line-height: 1.32;
  margin: 0 0 0.6rem;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.4);
}
.vtj-mustread-featured-desc {
  font-size: 0.88rem;
  color: #CBD5E1;
  line-height: 1.5;
  margin: 0 0 1.1rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}
.vtj-mustread-author-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
  color: #94A3B8;
}
.vtj-mustread-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  object-fit: cover;
  border: 1.5px solid #38BDF8;
}
.vtj-mustread-author-name {
  color: #FFFFFF;
  font-weight: 600;
}

/* Center Column (2 Compact Cards) */
.vtj-mustread-center-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}
.vtj-mustread-compact-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 14px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.03);
  display: flex;
  gap: 14px;
  align-items: center;
  flex: 1;
  text-decoration: none;
  color: inherit;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
html.dark .vtj-mustread-compact-card {
  background: #111827;
  border-color: #1E293B;
}
.vtj-mustread-compact-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.06);
  border-color: #CBD5E1;
}
html.dark .vtj-mustread-compact-card:hover {
  border-color: #334155;
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.35);
}
.vtj-mustread-compact-img-wrap {
  width: 42%;
  aspect-ratio: 16 / 10;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
  background: #0F172A;
}
.vtj-mustread-compact-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s ease;
}
.vtj-mustread-compact-card:hover .vtj-mustread-compact-img {
  transform: scale(1.03);
}
.vtj-mustread-compact-body {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
  flex-grow: 1;
}
.vtj-mustread-compact-title {
  font-family: var(--font-heading);
  font-size: 0.98rem;
  font-weight: 700;
  color: #0F172A;
  line-height: 1.35;
  margin: 0 0 0.4rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: color 0.2s ease;
}
html.dark .vtj-mustread-compact-title {
  color: #F8FAFC;
}
.vtj-mustread-compact-card:hover .vtj-mustread-compact-title {
  color: #2563EB;
}
.vtj-mustread-compact-meta {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.74rem;
  color: #94A3B8;
}

/* Right Column: Popular Articles */
.vtj-popular-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  padding: 18px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  display: flex;
  flex-direction: column;
}
html.dark .vtj-popular-card {
  background: #111827;
  border-color: #1E293B;
}
.vtj-popular-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.vtj-popular-item {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: inherit;
  padding-bottom: 12px;
  border-bottom: 1px solid #F1F5F9;
  transition: transform 0.2s ease;
}
html.dark .vtj-popular-item {
  border-bottom-color: #1E293B;
}
.vtj-popular-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.vtj-popular-item:hover {
  transform: translateX(3px);
}
.vtj-popular-rank {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 800;
  color: #3B82F6;
  line-height: 1;
  flex-shrink: 0;
  width: 24px;
  text-align: center;
}
.vtj-popular-img-wrap {
  width: 56px;
  height: 50px;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
  background: #0F172A;
}
.vtj-popular-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.vtj-popular-body {
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.vtj-popular-title {
  font-family: var(--font-heading);
  font-size: 0.86rem;
  font-weight: 700;
  color: #0F172A;
  line-height: 1.3;
  margin: 0 0 3px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: color 0.2s ease;
}
html.dark .vtj-popular-title {
  color: #F8FAFC;
}
.vtj-popular-item:hover .vtj-popular-title {
  color: #2563EB;
}
.vtj-popular-meta {
  font-size: 0.72rem;
  color: #94A3B8;
}

/* Responsive Media Queries for Section 8D */
@media (max-width: 1200px) {
  .vtj-devtools-layout {
    grid-template-columns: 1fr;
  }
  .vtj-mustread-layout {
    grid-template-columns: 1.2fr 1fr;
  }
  .vtj-popular-card {
    grid-column: 1 / -1;
  }
}
@media (max-width: 992px) {
  .vtj-devtools-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .vtj-mustread-layout {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 768px) {
  .vtj-devtools-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .vtj-devtool-card {
    padding: 0;
    border-radius: 12px;
    overflow: hidden;
  }
  .vtj-devtool-img-wrap {
    border-radius: 12px 12px 0 0;
    margin-bottom: 0;
    aspect-ratio: 16 / 9;
  }
  .vtj-devtool-body {
    padding: 14px 16px 16px;
  }
  .vtj-mustread-featured {
    min-height: 320px;
    padding: 20px;
  }
  .vtj-mustread-featured-title {
    font-size: 1.25rem;
  }
  .vtj-mustread-compact-card {
    flex-direction: column;
    padding: 0;
    border-radius: 12px;
    overflow: hidden;
  }
  .vtj-mustread-compact-img-wrap {
    width: 100%;
    aspect-ratio: 16 / 9;
    border-radius: 12px 12px 0 0;
  }
  .vtj-mustread-compact-body {
    width: 100%;
    padding: 14px 16px 16px;
    box-sizing: border-box;
  }
}

/* ============================================================
   10. ARTICLES PAGE (alphabetical listing)
============================================================ */
.articles-page-wrap {
  display: none;
  padding: 1.5rem 0;
}
.articles-page-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.25rem;
  margin-top: 1.5rem;
}
.articles-page-skeleton {
  grid-column: 1 / -1;
  text-align: center;
  color: var(--text-muted);
  padding: 3rem 0;
}
@media (max-width: 600px) {
  .articles-page-grid {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   11. TRENDING CATEGORIES
============================================================ */
.trending-section {
  padding: 2rem 0 2.5rem;
  border-bottom: 1px solid var(--border);
}
.trending-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.trending-label::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}
.trending-cats-row {
  display: flex;
  gap: 0.85rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  scrollbar-width: none;
}
.trending-cats-row::-webkit-scrollbar { display: none; }
.trend-cat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  flex-shrink: 0;
  transition: var(--transition);
  text-decoration: none;
  min-width: 100px;
}
html.dark .trend-cat-card { background: var(--bg-elevated); }
.trend-cat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}
.trend-cat-icon {
  width: 44px; height: 44px;
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
  transition: var(--transition);
}
.trend-cat-card:hover .trend-cat-icon { transform: scale(1.1); }
.trend-cat-name {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-secondary);
  text-align: center;
  white-space: nowrap;
  letter-spacing: 0.1px;
}
.trend-cat-card:hover .trend-cat-name { color: var(--primary); }
.tc-ai    { background: linear-gradient(135deg,rgba(37,99,235,0.12),rgba(124,58,237,0.12)); }
.tc-web   { background: linear-gradient(135deg,rgba(6,182,212,0.12),rgba(37,99,235,0.12)); }
.tc-apps  { background: linear-gradient(135deg,rgba(236,72,153,0.12),rgba(239,68,68,0.12)); }
.tc-edu   { background: linear-gradient(135deg,rgba(245,158,11,0.12),rgba(239,68,68,0.12)); }
.tc-prod  { background: linear-gradient(135deg,rgba(139,92,246,0.12),rgba(124,58,237,0.12)); }
.tc-soft  { background: linear-gradient(135deg,rgba(16,185,129,0.12),rgba(6,182,212,0.12)); }
.tc-sec   { background: linear-gradient(135deg,rgba(239,68,68,0.12),rgba(245,158,11,0.12)); }
.tc-rev   { background: linear-gradient(135deg,rgba(245,158,11,0.12),rgba(16,185,129,0.12)); }

/* ============================================================
   11. MAIN LAYOUT GRID & HOMEPAGE DESKTOP LAYOUT
============================================================ */
.main-layout {
  padding: 2.5rem 0 3rem;
  overflow: visible;
}
.main-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2.5rem;
  align-items: start;
}
.content-area { min-width: 0; }
.sidebar-area { min-width: 0; }

/* Homepage Only Responsive Layout */
.home-layout {
  width: calc(100% - 100px);
  max-width: 1600px;
  margin: 0 auto;
}
/* Hide old homepage latest articles & sidebar sections */
.main-layout.vtj-home-hidden,
.home-layout,
.home-main-grid,
.home-sidebar {
  display: none !important;
}

/* Section headers (for Latest Articles etc) */
.section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}
.section-head-left {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}
.section-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.3px;
  position: relative;
  padding-bottom: 0.5rem;
}
.section-title::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0;
  width: 36px; height: 3px;
  background: var(--gradient-main);
  border-radius: 2px;
}
.section-subtitle {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 0.4rem;
}
.section-view-all {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--primary);
  background: rgba(37,99,235,0.07);
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-full);
  border: 1px solid rgba(37,99,235,0.15);
  transition: var(--transition-fast);
}
.section-view-all:hover { background: var(--gradient-main); color: #fff; border-color: transparent; }
.section-view-all svg { width: 13px; height: 13px; fill: currentColor; }

/* ============================================================
   12. ARTICLE POST CARDS
============================================================ */
.posts-grid,
.latest-posts-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
  align-items: stretch;
}
.post-card,
.latest-post-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  position: relative;
}
html.dark .post-card,
html.dark .latest-post-card { background: var(--bg-elevated); }
.post-card:hover,
.latest-post-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-xl);
  border-color: rgba(37,99,235,0.2);
}
.post-card-thumb,
.latest-post-card-image {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  padding-top: 0;
  overflow: hidden;
  background: var(--bg-muted);
}
.post-card-thumb img,
.latest-post-card-image img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transition: var(--transition-slow);
}
.post-card:hover .post-card-thumb img,
.latest-post-card:hover .latest-post-card-image img { transform: scale(1.06); }
.post-card-thumb-placeholder {
  position: absolute;
  inset: 0;
  background: var(--gradient-main);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 800;
  color: rgba(255,255,255,0.5);
  letter-spacing: -0.5px;
}
.post-card-category {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background: var(--gradient-main);
  color: #fff;
  font-size: 0.62rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
  z-index: 1;
  white-space: nowrap;
  box-shadow: 0 2px 8px rgba(37,99,235,0.3);
}
.post-card-body,
.latest-post-card-content {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 0.75rem;
}
.post-card-title {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  letter-spacing: -0.1px;
}
.post-card-title a { color: inherit; }
.post-card-title a:hover { color: var(--primary); }
.post-card-excerpt {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.55;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.post-card-footer,
.latest-post-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 0.85rem;
  border-top: 1px solid var(--border);
}
.post-card-meta {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.75rem;
  color: var(--text-faint);
}
.post-card-meta svg { width: 12px; height: 12px; fill: currentColor; }
.post-card-meta-dot { width: 3px; height: 3px; background: var(--border); border-radius: 50%; }
.post-card-readmore {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.25rem;
  white-space: nowrap;
}
.post-card-readmore svg { width: 12px; height: 12px; fill: currentColor; transition: var(--transition-fast); }
.post-card:hover .post-card-readmore svg { transform: translateX(2px); }

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  margin-top: 2.5rem;
  flex-wrap: wrap;
}
.pagination-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-width: 40px;
  height: 40px;
  padding: 0 0.85rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: var(--transition-fast);
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  box-sizing: border-box;
}
html.dark .pagination-btn { background: var(--bg-elevated); }
.pagination-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(37,99,235,0.06);
}
.pagination-prev,
.pagination-next {
  padding: 0 1rem;
  gap: 0.4rem;
}
.pagination-num {
  min-width: 40px;
  font-weight: 700;
}
.pagination-active {
  background: var(--gradient-main) !important;
  color: #fff !important;
  border-color: transparent !important;
  cursor: default;
  box-shadow: 0 2px 8px rgba(37,99,235,0.25);
}
html.dark .pagination-active {
  box-shadow: 0 2px 8px rgba(37,99,235,0.35);
}
.pagination-disabled {
  color: var(--text-muted) !important;
  background: var(--bg-muted) !important;
  border-color: var(--border) !important;
  cursor: default;
  pointer-events: none;
}
.pagination-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 40px;
  font-size: 1rem;
  color: var(--text-faint);
  letter-spacing: 1px;
  user-select: none;
}

/* Empty state */
.empty-state {
  text-align: center;
  padding: 4rem 2rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
}
html.dark .empty-state { background: var(--bg-elevated); }
.empty-state h3 { font-family: var(--font-heading); font-size: 1.25rem; font-weight: 700; margin-bottom: 0.5rem; }
.empty-state p { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.5rem; }
.empty-state-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--gradient-main);
  color: #fff;
  padding: 0.65rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9rem;
}

/* ============================================================
   13. SIDEBAR WIDGETS
============================================================ */
.sidebar-area {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.widget-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xs);
}
html.dark .widget-box { background: var(--bg-elevated); }
.widget-header {
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.5rem;
}
.widget-title {
  font-family: var(--font-heading);
  font-size: 0.88rem;
  font-weight: 800;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  position: relative;
  padding-left: 0.75rem;
}
.widget-title::before {
  content: '';
  position: absolute;
  left: 0; top: 50%;
  transform: translateY(-50%);
  width: 3px; height: 16px;
  background: var(--gradient-main);
  border-radius: 2px;
}
.widget-body { padding: 1.25rem; }
.widget-body-flush { padding: 0; }
.widget-header-logo {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
}
.widget-header-logo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.widget-header-logo svg { width: 100%; height: 100%; display: block; padding: 4px; }
.widget-header-logo + .widget-title { padding-left: 0; }
.widget-header-logo + .widget-title::before { display: none; }

/* Sidebar Search */
.sidebar-search-form {
  display: flex;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition-fast);
}
.sidebar-search-form:focus-within { border-color: var(--primary); }
.sidebar-search-input {
  flex: 1;
  border: none;
  outline: none;
  padding: 0.7rem 1rem;
  font-size: 0.88rem;
  background: transparent;
  color: var(--text-primary);
}
.sidebar-search-btn {
  background: var(--gradient-main);
  border: none;
  padding: 0 1rem;
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition-fast);
}
.sidebar-search-btn:hover { opacity: 0.9; }
.sidebar-search-btn svg { width: 16px; height: 16px; fill: currentColor; }

/* About widget */
.about-logo-img-wrap {
  text-align: center;
  margin-bottom: 0.75rem;
}
.about-logo-img-wrap img {
  max-width: 120px;
  height: auto;
  display: inline-block;
  border-radius: var(--radius-sm);
}
.about-logo-text {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
  text-align: center;
}
.about-logo-text .logo-accent {
  background: var(--gradient-main);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.about-text { font-size: 0.85rem; color: var(--text-muted); line-height: 1.6; text-align: center; }

/* Popular posts (vertical marquee) */
.popular-posts-marquee-wrap {
  height: 340px;
  overflow: hidden;
  position: relative;
}
.popular-posts-marquee-wrap::before,
.popular-posts-marquee-wrap::after {
  content: '';
  position: absolute;
  left: 0; right: 0;
  height: 20px;
  z-index: 2;
  pointer-events: none;
}
.popular-posts-marquee-wrap::before {
  top: 0;
  background: linear-gradient(to bottom, var(--bg-card) 0%, transparent 100%);
}
html.dark .popular-posts-marquee-wrap::before { background: linear-gradient(to bottom, var(--bg-elevated) 0%, transparent 100%); }
.popular-posts-marquee-wrap::after {
  bottom: 0;
  background: linear-gradient(to top, var(--bg-card) 0%, transparent 100%);
}
html.dark .popular-posts-marquee-wrap::after { background: linear-gradient(to top, var(--bg-elevated) 0%, transparent 100%); }
.popular-posts-marquee-inner {
  animation: popularMarquee 30s linear infinite;
}
.popular-posts-marquee-wrap:hover .popular-posts-marquee-inner {
  animation-play-state: paused;
}
@keyframes popularMarquee {
  0% { transform: translateY(0); }
  100% { transform: translateY(-50%); }
}
.popular-post-item {
  display: flex;
  gap: 0.85rem;
  align-items: center;
  padding: 0.85rem 1.25rem;
  border-bottom: 1px solid var(--border);
  transition: var(--transition-fast);
}
.popular-post-item:last-child { border-bottom: none; }
.popular-post-item:hover { background: rgba(37,99,235,0.04); }
html.dark .popular-post-item:hover { background: rgba(255,255,255,0.03); }
.popular-post-thumb {
  width: 60px; height: 50px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  flex-shrink: 0;
  background: var(--bg-muted);
}
.popular-post-thumb img { width: 100%; height: 100%; object-fit: cover; }
.popular-post-info { flex: 1; min-width: 0; }
.popular-post-title {
  font-family: var(--font-heading);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 0.2rem;
}
.popular-post-item:hover .popular-post-title { color: var(--primary); }
.popular-post-date { font-size: 0.7rem; color: var(--text-faint); }

/* Categories */
.categories-scroll {
  max-height: 250px;
  overflow-y: auto;
}
.categories-scroll::-webkit-scrollbar { width: 4px; }
.categories-scroll::-webkit-scrollbar-track { background: transparent; }
.categories-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
.labels-grid-2col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}
.label-block {
  display: block;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-muted);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.55rem 0.75rem;
  transition: var(--transition-fast);
  text-align: left;
  line-height: 1.3;
}
html.dark .label-block { background: rgba(255,255,255,0.04); }
.label-block:hover {
  background: var(--gradient-main);
  color: #fff;
  border-color: transparent;
}

/* Newsletter widget */
.newsletter-widget-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.newsletter-widget-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.6;
}
.newsletter-widget-input {
  width: 100%;
  padding: 0.7rem 1rem;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg-muted);
  color: var(--text-primary);
  font-size: 0.85rem;
  outline: none;
  transition: var(--transition-fast);
  box-sizing: border-box;
}
.newsletter-widget-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(37,99,235,0.1); }
.newsletter-widget-btn {
  width: 100%;
  padding: 0.7rem;
  background: var(--gradient-main);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 0.85rem;
  cursor: pointer;
  transition: var(--transition);
  letter-spacing: 0.3px;
}
.newsletter-widget-btn:hover { transform: translateY(-2px); box-shadow: var(--shadow-colored); }
.newsletter-privacy-note {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-align: center;
}

/* Social profile cards */
.social-profile-card { transition: transform 0.3s ease, box-shadow 0.3s ease; }
.social-profile-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.social-profile-body {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.6rem;
}
.social-profile-avatar-wrap {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  overflow: hidden;
  border: 3px solid var(--border);
  background: var(--bg-muted);
  flex-shrink: 0;
  transition: transform 0.3s ease;
}
.social-profile-card:hover .social-profile-avatar-wrap { transform: scale(1.03); }
.social-profile-avatar { width: 100%; height: 100%; }
.social-profile-avatar img { width: 100%; height: 100%; object-fit: cover; display: block; }
.social-profile-name {
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
}
.social-profile-subtitle {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.4;
  margin: 0;
}
.social-profile-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.55rem 1.25rem;
  border: none;
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  text-decoration: none;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  width: 100%;
  box-sizing: border-box;
}
.social-profile-btn svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
  flex-shrink: 0;
}
.social-profile-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,0.25); }
.social-profile-btn-yt { background: linear-gradient(135deg, #FF0000, #CC0000); }
.social-profile-btn-ig { background: linear-gradient(135deg, #F58529, #DD2A7B, #8134AF); }
.social-profile-note {
  font-size: 0.72rem;
  color: var(--text-muted);
  line-height: 1.4;
  margin: 0;
}
.widget-box.social-profile-card + .widget-box.social-profile-card { margin-top: 10px; }

/* Social follow */
.social-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}
.social-follow-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  padding: 0.7rem 0.5rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-muted);
  color: var(--text-muted);
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: var(--transition-fast);
  cursor: pointer;
}
.social-follow-btn svg { width: 18px; height: 18px; fill: currentColor; }
.social-follow-btn:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.social-follow-btn[title="YouTube"]:hover svg { fill: #FF0000; }
.social-follow-btn[title="YouTube"]:hover { border-color: #FF0000; color: #FF0000; }
.social-follow-btn[title="Instagram"]:hover svg { fill: #E1306C; }
.social-follow-btn[title="Instagram"]:hover { border-color: #E1306C; color: #E1306C; }
.social-follow-btn[title="Facebook"]:hover svg { fill: #1877F2; }
.social-follow-btn[title="Facebook"]:hover { border-color: #1877F2; color: #1877F2; }
.social-follow-btn[title="Twitter"]:hover svg { fill: #000; }
.social-follow-btn[title="Twitter"]:hover { border-color: #000; color: #000; }
.social-follow-btn[title="LinkedIn"]:hover svg { fill: #0A66C2; }
.social-follow-btn[title="LinkedIn"]:hover { border-color: #0A66C2; color: #0A66C2; }
html.dark .social-follow-btn[title="Twitter"]:hover { color: #fff; }
html.dark .social-follow-btn[title="Twitter"]:hover svg { fill: #fff; }

.skel {
  background: linear-gradient(90deg, var(--border) 25%, var(--bg-muted) 50%, var(--border) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.6s infinite;
}
@keyframes shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ============================================================
   14. MAGAZINE CATEGORY BLOCKS
============================================================ */
.magazine-blocks-section { padding: 1rem 0 3rem; }
.magazine-block { margin-bottom: 3rem; }
.mag-inner {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 1.5rem;
  align-items: start;
}
/* Large card */
.mag-large-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  height: 100%;
  transition: var(--transition);
}
html.dark .mag-large-card { background: var(--bg-elevated); }
.mag-large-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); border-color: rgba(37,99,235,0.2); }
.mag-large-img {
  position: relative;
  width: 100%; padding-top: 58%;
  overflow: hidden;
}
.mag-large-img img {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transition: var(--transition-slow);
}
.mag-large-card:hover .mag-large-img img { transform: scale(1.05); }
.mag-large-badge {
  position: absolute; top: 0.75rem; left: 0.75rem;
  background: var(--gradient-main);
  color: #fff; font-size: 0.6rem; font-weight: 800;
  text-transform: uppercase; letter-spacing: 1px;
  padding: 0.25rem 0.6rem; border-radius: var(--radius-full);
  z-index: 1;
}
.mag-large-body { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; gap: 0.75rem; }
.mag-large-cat {
  font-size: 0.65rem; font-weight: 800; text-transform: uppercase;
  letter-spacing: 1px; color: var(--primary);
}
.mag-large-title {
  font-family: var(--font-heading); font-size: 1.15rem; font-weight: 800;
  color: var(--text-primary); line-height: 1.35; letter-spacing: -0.2px;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.mag-large-title a { color: inherit; }
.mag-large-title a:hover { color: var(--primary); }
.mag-large-excerpt {
  font-size: 0.85rem; color: var(--text-muted); line-height: 1.55;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.mag-large-meta {
  display: flex; align-items: center; gap: 0.5rem;
  font-size: 0.73rem; color: var(--text-faint); margin-top: auto;
}
.mag-large-meta-dot { width: 3px; height: 3px; background: var(--border); border-radius: 50%; }

/* Small cards */
.mag-small-group { display: flex; flex-direction: column; gap: 0.85rem; }
.mag-small-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  gap: 0;
  transition: var(--transition);
  box-shadow: var(--shadow-xs);
}
html.dark .mag-small-card { background: var(--bg-elevated); }
.mag-small-card:hover { transform: translateX(4px); box-shadow: var(--shadow-md); border-color: rgba(37,99,235,0.2); }
.mag-small-img {
  width: 96px; flex-shrink: 0;
  position: relative; overflow: hidden;
}
.mag-small-img img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: cover;
  transition: var(--transition);
}
.mag-small-card:hover .mag-small-img img { transform: scale(1.06); }
.mag-small-body { padding: 0.85rem 1rem; display: flex; flex-direction: column; gap: 0.35rem; flex: 1; min-width: 0; }
.mag-small-cat {
  font-size: 0.6rem; font-weight: 800; text-transform: uppercase;
  letter-spacing: 0.8px; color: var(--primary);
}
.mag-small-title {
  font-family: var(--font-heading); font-size: 0.85rem; font-weight: 700;
  color: var(--text-primary); line-height: 1.35;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.mag-small-title a { color: inherit; }
.mag-small-title a:hover { color: var(--primary); }
.mag-small-date { font-size: 0.68rem; color: var(--text-faint); }

/* mag block skeleton */
.mag-skel { border-radius: var(--radius-md); overflow: hidden; }
.mag-skel-img { width: 100%; height: 200px; }
.mag-skel-body { padding: 1rem; display: flex; flex-direction: column; gap: 8px; }
.mag-skel-line { height: 12px; border-radius: 4px; }

/* ============================================================
   15. NEWSLETTER SECTION (Full Width)
============================================================ */
.newsletter-fullwidth {
  margin: 0 0 3rem;
  background: linear-gradient(135deg, #1a237e 0%, #2563EB 40%, #7C3AED 100%);
  border-radius: var(--radius-xl);
  overflow: hidden;
  position: relative;
}
.newsletter-fullwidth::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 250px; height: 250px;
  background: rgba(255,255,255,0.06);
  border-radius: 50%;
}
.newsletter-fullwidth::after {
  content: '';
  position: absolute;
  bottom: -80px; left: 40px;
  width: 200px; height: 200px;
  background: rgba(255,255,255,0.04);
  border-radius: 50%;
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2.5rem;
  align-items: center;
  padding: 3.5rem;
  position: relative;
  z-index: 2;
}
.newsletter-text-col { display: flex; flex-direction: column; gap: 0.75rem; }
.newsletter-eyebrow {
  font-size: 0.7rem; font-weight: 800; text-transform: uppercase;
  letter-spacing: 2px; color: rgba(255,255,255,0.6);
}
.newsletter-heading {
  font-family: var(--font-heading); font-size: 1.85rem; font-weight: 800;
  color: #fff; line-height: 1.25; letter-spacing: -0.5px;
}
.newsletter-subtext { font-size: 0.92rem; color: rgba(255,255,255,0.7); line-height: 1.55; max-width: 480px; }
.newsletter-form-col { flex-shrink: 0; }
.newsletter-form-group {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-width: 320px;
}
.newsletter-form-input {
  padding: 0.85rem 1.25rem;
  border-radius: var(--radius-md);
  border: none;
  background: rgba(255,255,255,0.12);
  backdrop-filter: blur(8px);
  color: #fff;
  font-size: 0.9rem;
  outline: none;
  border: 1.5px solid rgba(255,255,255,0.2);
  transition: var(--transition-fast);
}
.newsletter-form-input::placeholder { color: rgba(255,255,255,0.45); }
.newsletter-form-input:focus { border-color: rgba(255,255,255,0.5); background: rgba(255,255,255,0.18); }
.newsletter-form-btn {
  padding: 0.85rem 1.5rem;
  background: #fff;
  color: var(--primary);
  border: none;
  border-radius: var(--radius-md);
  font-weight: 800;
  font-size: 0.9rem;
  cursor: pointer;
  transition: var(--transition);
  letter-spacing: 0.2px;
}
.newsletter-form-btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.2); }
.newsletter-disclaimer { font-size: 0.7rem; color: rgba(255,255,255,0.4); margin-top: 0.25rem; }

/* ============================================================
   16. SINGLE POST LAYOUT
============================================================ */
.single-post-wrapper { padding: 0 0 3rem; }
.single-post-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2.5rem;
  align-items: start;
}
.post-body-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
}
html.dark .post-body-card { background: var(--bg-elevated); }
.post-header-section { padding: 2.5rem 2.5rem 0; }
.post-breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.75rem;
  color: var(--text-faint);
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}
.post-breadcrumb a { color: var(--text-muted); }
.post-breadcrumb a:hover { color: var(--primary); }
.post-breadcrumb svg { width: 10px; height: 10px; fill: currentColor; }
.post-labels-row {
  display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 1rem;
}
.post-label-tag {
  font-size: 0.65rem; font-weight: 800; text-transform: uppercase;
  letter-spacing: 1px; color: var(--primary);
  background: rgba(37,99,235,0.08);
  border: 1px solid rgba(37,99,235,0.2);
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-full);
  transition: var(--transition-fast);
}
.post-label-tag:hover { background: var(--gradient-main); color: #fff; border-color: transparent; }
.post-main-title {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.5px;
  margin-bottom: 1.25rem;
  background: linear-gradient(90deg, var(--primary), var(--secondary), var(--accent), var(--secondary), var(--primary));
  background-size: 300% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: logo-shimmer 5s ease-in-out infinite;
}
.post-author-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border);
}
.post-author-avatar {
  width: 42px; height: 42px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid rgba(37,99,235,0.3);
  flex-shrink: 0;
  background: var(--gradient-main);
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; color: #fff; font-size: 0.85rem;
}
.post-author-avatar img { width: 100%; height: 100%; object-fit: cover; }
.post-author-info { display: flex; flex-direction: column; gap: 0.2rem; }
.post-author-name { font-weight: 700; font-size: 0.88rem; color: var(--text-primary); }
.post-author-meta {
  display: flex; align-items: center; gap: 0.5rem;
  font-size: 0.75rem; color: var(--text-faint);
}
.post-author-meta-dot { width: 3px; height: 3px; background: var(--border); border-radius: 50%; }
.post-author-meta svg { width: 11px; height: 11px; fill: currentColor; }
.post-featured-img {
  width: 100%; aspect-ratio: 16/9;
  object-fit: cover;
  display: block;
  margin: 1.5rem 0 0;
}
/* Post body content */
.post-content {
  padding: 1.25rem 2.5rem 2rem;
  font-size: 1.05rem; line-height: 1.65; color: var(--text-secondary);
}
.post-content p { margin: 0 0 0.75rem; padding: 0; }
.post-content p:last-child { margin-bottom: 0; }
.post-content h2 {
  font-family: var(--font-heading); font-size: 1.5rem; font-weight: 800;
  color: var(--text-primary); margin: 1.5rem 0 0.65rem; letter-spacing: -0.3px;
  border-left: 4px solid var(--primary); padding-left: 1rem;
}
.post-content h3 {
  font-family: var(--font-heading); font-size: 1.2rem; font-weight: 700;
  color: var(--text-primary); margin: 1.25rem 0 0.55rem;
}
.post-content img { display: block; max-width: 100%; height: auto; margin: 0.75rem auto; padding: 0; border-radius: var(--radius-md); }
.post-content .separator { display: block; clear: both; margin: 0.75rem 0; padding: 0; line-height: 0; text-align: center; }
.post-content .separator a { display: inline-block; margin: 0; padding: 0; line-height: 0; }
.post-content .separator img { margin: 0 auto; padding: 0; }
.post-content p:has(> img:only-child),
.post-content p:has(> a:only-child > img:only-child) { margin: 0.75rem 0; padding: 0; line-height: 0; }
.post-content ul { padding-left: 1.5rem; margin: 0.5rem 0 0.85rem; list-style: disc; }
.post-content ol { padding-left: 1.5rem; margin: 0.5rem 0 0.85rem; list-style: decimal; }
.post-content li { margin-bottom: 0.3rem; }
.post-content blockquote {
  border-left: 4px solid var(--secondary); background: var(--bg-muted);
  padding: 1.25rem 1.5rem; border-radius: 0 var(--radius-md) var(--radius-md) 0;
  margin: 1rem 0; font-style: italic; color: var(--text-muted);
}
.post-content a { color: var(--primary); text-decoration: underline; text-underline-offset: 3px; }
.post-table-scroll {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  margin: 1rem 0 !important;
  padding: 0 !important;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

#post-content table,
.post-content table,
#post-content table.vtj-post-table {
  display: table !important;
  width: 100% !important;
  min-width: 680px !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  table-layout: auto !important;
  border-collapse: collapse !important;
  border-spacing: 0 !important;
  border: 1px solid var(--border) !important;
  background: var(--bg-card) !important;
  color: var(--text-secondary) !important;
  font-family: var(--font-sans) !important;
  font-size: 0.9rem !important;
  line-height: 1.45 !important;
}

#post-content table thead,
.post-content table thead {
  display: table-header-group !important;
}

#post-content table tbody,
.post-content table tbody {
  display: table-row-group !important;
}

#post-content table tr,
.post-content table tr {
  display: table-row !important;
  height: auto !important;
  min-height: 0 !important;
  background: transparent !important;
}

#post-content table th,
#post-content table td,
.post-content table th,
.post-content table td {
  display: table-cell !important;
  height: auto !important;
  min-height: 0 !important;
  padding: 0.75rem 1rem !important;
  border: 1px solid var(--border) !important;
  text-align: left !important;
  vertical-align: middle !important;
  white-space: normal !important;
  word-break: normal !important;
  overflow-wrap: break-word !important;
  box-sizing: border-box !important;
  position: static !important;
  float: none !important;
}

#post-content table th,
.post-content table th {
  background: rgba(37, 99, 235, 0.07) !important;
  color: var(--text-primary) !important;
  font-weight: 700 !important;
}

#post-content table td,
.post-content table td {
  background: var(--bg-card) !important;
  color: var(--text-secondary) !important;
  font-weight: 400 !important;
}

#post-content table tbody tr:nth-child(even) td,
.post-content table tbody tr:nth-child(even) td {
  background: rgba(148, 163, 184, 0.055) !important;
}

#post-content table tr:hover td,
.post-content table tr:hover td {
  background: rgba(37, 99, 235, 0.055) !important;
}

html.dark #post-content table,
html.dark .post-content table {
  background: var(--bg-elevated) !important;
  border-color: var(--border) !important;
}

html.dark #post-content table th,
html.dark .post-content table th {
  background: rgba(96, 165, 250, 0.12) !important;
  color: var(--text-primary) !important;
  border-color: var(--border) !important;
}

html.dark #post-content table td,
html.dark .post-content table td {
  background: var(--bg-elevated) !important;
  color: var(--text-secondary) !important;
  border-color: var(--border) !important;
}

@media (max-width: 768px) {
  #post-content table,
  .post-content table,
  #post-content table.vtj-post-table {
    min-width: 650px !important;
    font-size: 0.84rem !important;
  }

  #post-content table th,
  #post-content table td,
  .post-content table th,
  .post-content table td {
    padding: 0.65rem 0.8rem !important;
  }
}
.post-content p:empty,
.post-content div:empty { display: none; margin: 0; padding: 0; }
.post-content br:first-child,
.post-content br:last-child { display: none; }

/* ============================================================
   PREMIUM CODE BLOCK STYLES (Light & Dark Theme Responsive)
============================================================ */
.post-content pre,
.post-body pre,
#post-content pre {
  margin: 1.25rem 0;
  padding: 0;
  background: transparent;
  border: none;
  overflow: visible;
}

/* Light mode default */
.vtj-code-block {
  position: relative;
  margin: 1.5rem 0;
  border-radius: var(--radius-lg, 12px);
  background: #f6f8fa;
  border: 1px solid #d0d7de;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.05);
  overflow: hidden;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 0.9rem;
  line-height: 1.6;
  color: #1f2328;
  transition: background 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

.vtj-code-block:hover {
  border-color: #afb8c1;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08);
}

.vtj-code-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.55rem 1rem;
  background: #eaeef2;
  border-bottom: 1px solid #d0d7de;
  user-select: none;
  transition: background 0.25s ease, border-color 0.25s ease;
}

.vtj-code-lang {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #57606a;
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.vtj-code-lang::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--primary, #2563eb);
}

.vtj-code-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.vtj-code-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.32rem 0.68rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #24292f;
  background: rgba(0, 0, 0, 0.05);
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  font-family: inherit;
  line-height: 1;
}

.vtj-code-btn:hover {
  background: rgba(0, 0, 0, 0.1);
  color: #000000;
  border-color: rgba(0, 0, 0, 0.22);
}

.vtj-code-btn:focus-visible {
  box-shadow: 0 0 0 2px var(--primary, #2563eb);
}

.vtj-code-btn svg {
  width: 13px;
  height: 13px;
  fill: currentColor;
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.vtj-code-btn.is-copied {
  background: rgba(34, 197, 94, 0.15);
  color: #15803d;
  border-color: rgba(34, 197, 94, 0.4);
}

.vtj-code-btn.is-copied svg {
  transform: scale(1.1);
}

.vtj-code-wrapper {
  position: relative;
  width: 100%;
  max-width: 100%;
  max-height: 300px;
  overflow-y: auto;
  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color: #d0d7de #f6f8fa;
  -webkit-overflow-scrolling: touch;
  transition: max-height 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.vtj-code-wrapper.is-expanded {
  max-height: none !important;
  overflow-y: visible;
}

.vtj-code-wrapper pre {
  margin: 0 !important;
  padding: 1rem 1.15rem !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace !important;
  font-size: 0.88rem !important;
  line-height: 1.65 !important;
  color: #1f2328 !important;
  white-space: pre !important;
  word-break: normal !important;
  word-wrap: normal !important;
  tab-size: 4;
  -moz-tab-size: 4;
}

.vtj-code-wrapper code {
  font-family: inherit !important;
  font-size: inherit !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  color: inherit !important;
  white-space: pre !important;
}

.vtj-code-wrapper::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.vtj-code-wrapper::-webkit-scrollbar-track {
  background: #f6f8fa;
}

.vtj-code-wrapper::-webkit-scrollbar-thumb {
  background: #d0d7de;
  border-radius: 4px;
}

.vtj-code-wrapper::-webkit-scrollbar-thumb:hover {
  background: #afb8c1;
}

.vtj-code-wrapper::-webkit-scrollbar-corner {
  background: #f6f8fa;
}

/* Dark mode theme overrides */
html.dark .vtj-code-block {
  background: #0d1117;
  border-color: #30363d;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);
  color: #e6edf3;
}

html.dark .vtj-code-block:hover {
  border-color: #484f58;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
}

html.dark .vtj-code-header {
  background: #161b22;
  border-bottom-color: #30363d;
}

html.dark .vtj-code-lang {
  color: #8b949e;
}

html.dark .vtj-code-lang::before {
  background: #38bdf8;
}

html.dark .vtj-code-btn {
  color: #c9d1d9;
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.12);
}

html.dark .vtj-code-btn:hover {
  background: rgba(255, 255, 255, 0.14);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.25);
}

html.dark .vtj-code-btn.is-copied {
  background: rgba(34, 197, 94, 0.15);
  color: #4ade80;
  border-color: rgba(34, 197, 94, 0.4);
}

html.dark .vtj-code-wrapper {
  scrollbar-color: #30363d #0d1117;
}

html.dark .vtj-code-wrapper pre {
  color: #e6edf3 !important;
}

html.dark .vtj-code-wrapper::-webkit-scrollbar-track {
  background: #0d1117;
}

html.dark .vtj-code-wrapper::-webkit-scrollbar-thumb {
  background: #30363d;
}

html.dark .vtj-code-wrapper::-webkit-scrollbar-thumb:hover {
  background: #484f58;
}

html.dark .vtj-code-wrapper::-webkit-scrollbar-corner {
  background: #0d1117;
}

.post-content code:not(pre code),
.post-body code:not(pre code),
#post-content code:not(pre code) {
  background: rgba(110, 118, 129, 0.18);
  color: var(--primary, #2563eb);
  padding: 0.18rem 0.45rem;
  border-radius: 4px;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 0.85em;
  border: 1px solid rgba(110, 118, 129, 0.2);
}

html.dark .post-content code:not(pre code),
html.dark .post-body code:not(pre code),
html.dark #post-content code:not(pre code) {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
  border-color: rgba(56, 189, 248, 0.25);
}

@media (max-width: 600px) {
  .vtj-code-header {
    padding: 0.45rem 0.75rem;
  }
  .vtj-code-wrapper pre {
    padding: 0.85rem 0.85rem !important;
    font-size: 0.82rem !important;
  }
  .vtj-code-btn {
    padding: 0.25rem 0.5rem;
    font-size: 0.7rem;
  }
}

/* Share bar */
.share-bar {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 1rem;
  margin: 0 2.5rem 2.5rem;
  padding: 1.25rem;
  background: var(--bg-muted);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}
.share-bar-label { font-size: 0.82rem; font-weight: 700; color: var(--text-muted); }
.share-btns { display: flex; gap: 0.5rem; }
.share-btn {
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%; color: #fff; transition: var(--transition);
}
.share-btn:hover { transform: translateY(-2px); filter: brightness(1.15); }
.share-btn svg { width: 15px; height: 15px; fill: currentColor; }
.share-fb { background: #1877F2; }
.share-tw { background: #000; }
.share-li { background: #0A66C2; }
.share-pi { background: #E60023; }
.share-copy { background: var(--bg-elevated); border: 1px solid var(--border); color: var(--text-muted); cursor: pointer; }
html.dark .share-copy { background: var(--bg-dark-card); }
.share-copy:hover { background: var(--gradient-main); border-color: transparent; color: #fff; }
/* Author bio */
.author-bio {
  display: flex; gap: 1.25rem; align-items: flex-start;
  margin: 0 2.5rem 2.5rem;
  padding: 1.5rem;
  background: var(--bg-muted);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}
.author-bio-avatar {
  width: 60px; height: 60px; border-radius: 50%;
  overflow: hidden; flex-shrink: 0; border: 3px solid rgba(37,99,235,0.2);
  background: var(--gradient-main);
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; color: #fff; font-size: 1.25rem;
}
.author-bio-avatar img { width: 100%; height: 100%; object-fit: cover; }
.author-bio-content { flex: 1; }
.author-bio-name { font-family: var(--font-heading); font-size: 1rem; font-weight: 800; color: var(--text-primary); margin-bottom: 0.35rem; }
.author-bio-text { font-size: 0.85rem; color: var(--text-muted); line-height: 1.55; }
/* ----- Related Posts Carousel ----- */
:root {
  --carousel-speed: 30s;
  --carousel-direction: normal;
  --carousel-card-width: 260px;
  --carousel-gap: 1rem;
}
.related-section {
  margin: 0 2.5rem 2.5rem;
  overflow: hidden;
}
.related-title {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 800;
  margin-bottom: 1.25rem;
  color: var(--text-primary);
}
.related-carousel {
  position: relative;
  width: 100%;
  overflow: hidden;
}
.related-track {
  display: flex;
  gap: var(--carousel-gap);
  width: max-content;
  animation: scroll var(--carousel-speed) linear infinite;
  animation-direction: var(--carousel-direction);
}
.related-carousel.paused .related-track {
  animation-play-state: paused;
}
.related-carousel.reverse .related-track {
  animation-direction: reverse;
}
@keyframes scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
.related-card {
  width: var(--carousel-card-width);
  flex-shrink: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
}
html.dark .related-card { background: var(--bg-dark-card); }
.related-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.related-card-img {
  position: relative;
  width: 100%;
  padding-top: 56.25%;
  overflow: hidden;
  background: var(--bg-muted);
}
/* Placeholder gradient background when no image - matches post-card style */
.related-card-img::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #e8e8e8 0%, #f5f5f5 100%);
  z-index: 1;
}
html.dark .related-card-img::before {
  background: linear-gradient(135deg, #2a2a2a 0%, #3a3a3a 100%);
}
/* High-quality image - no blur, no filter, no quality reduction */
.related-card-img img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  /* No filter, blur, or image-rendering that reduces quality */
  z-index: 2;
  transition: transform 0.4s ease;
}
/* Subtle zoom on hover only */
.related-card:hover .related-card-img img {
  transform: scale(1.05);
}
.related-card-body {
  padding: 0.85rem;
}
.related-card-title {
  font-family: var(--font-heading);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.related-card-title a { color: inherit; }
.related-card-title a:hover { color: var(--primary); }
@media (max-width: 768px) {
  :root {
    --carousel-card-width: 200px;
    --carousel-gap: 0.75rem;
  }
}
@media (max-width: 480px) {
  :root {
    --carousel-card-width: 170px;
    --carousel-gap: 0.5rem;
  }
}
/* Post nav */
.post-nav { display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; margin: 0 2.5rem 2.5rem; }
.post-nav-btn {
  display: flex; align-items: center; gap: 0.85rem;
  padding: 1.1rem; background: var(--bg-muted);
  border: 1px solid var(--border); border-radius: var(--radius-md);
  transition: var(--transition);
}
.post-nav-btn:hover { border-color: var(--primary); background: rgba(37,99,235,0.05); transform: translateY(-2px); }
.post-nav-btn svg { width: 18px; height: 18px; fill: var(--text-muted); flex-shrink: 0; }
.post-nav-btn:hover svg { fill: var(--primary); }
.post-nav-label { font-size: 0.68rem; color: var(--text-faint); text-transform: uppercase; font-weight: 700; }
.post-nav-ptitle { font-family: var(--font-heading); font-size: 0.85rem; font-weight: 700; color: var(--text-primary); margin-top: 0.2rem; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.post-nav-next { text-align: right; justify-content: flex-end; }
/* Comments */
.post-comments { padding: 2rem 2.5rem; border-top: 1px solid var(--border); }
#comments .title { font-family: var(--font-heading); font-size: 1.1rem; font-weight: 800; color: var(--text-primary); margin-bottom: 1.5rem; }
.comment-block { background: var(--bg-muted) !important; border-radius: var(--radius-md) !important; border: 1px solid var(--border) !important; padding: 1rem !important; margin-left: 40px !important; }
.avatar-image-container img { border-radius: 50% !important; }

/* ============================================================
   17. FOOTER
============================================================ */
.site-footer {
  background: #0A0F1E;
  color: #94A3B8;
  margin-top: auto;
  position: relative;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.site-footer::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 1200px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(59, 130, 246, 0.4), rgba(168, 85, 247, 0.4), transparent);
  pointer-events: none;
}
.footer-top { padding: 48px 0 32px; border-bottom: 1px solid rgba(255, 255, 255, 0.06); }
.footer-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr 1.3fr;
  gap: 32px;
  align-items: start;
}
.footer-col { display: flex; flex-direction: column; gap: 0.85rem; }
.footer-logo-wrapper { display: flex; align-items: center; gap: 12px; }
.footer-logo-text {
  font-family: var(--font-heading); font-size: 1.35rem; font-weight: 800;
  color: #FFFFFF; letter-spacing: -0.5px; line-height: 1.2; margin: 0;
}
.footer-logo-text .logo-accent {
  background: linear-gradient(135deg, #3B82F6 0%, #A855F7 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
}
.footer-logo-img {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  border: 2px solid rgba(255, 255, 255, 0.15);
}
.footer-tagline { font-size: 0.7rem; font-weight: 700; color: #3B82F6; text-transform: uppercase; letter-spacing: 1.5px; margin-top: 2px; }
.footer-about { font-size: 0.84rem; line-height: 1.6; color: #94A3B8; margin-top: 4px; }
.footer-col-title {
  font-family: var(--font-heading); font-size: 0.82rem; font-weight: 700;
  color: #FFFFFF; text-transform: uppercase; letter-spacing: 1px;
  margin-bottom: 14px; padding-bottom: 8px; border-bottom: 2px solid rgba(37, 99, 235, 0.3);
  position: relative; display: inline-block;
}
.footer-col-title::after {
  content: ''; position: absolute; bottom: -2px; left: 0; width: 24px; height: 2px;
  background: linear-gradient(90deg, #2563EB, #7C3AED);
}
.footer-links { display: flex; flex-direction: column; gap: 8px; }
.footer-link {
  font-size: 0.85rem; color: #94A3B8; transition: all 0.2s ease;
  display: inline-flex; align-items: center; gap: 8px; text-decoration: none;
}
.footer-link svg {
  width: 14px; height: 14px; fill: none; stroke: #3B82F6; stroke-width: 2.5;
  stroke-linecap: round; stroke-linejoin: round; transition: transform 0.2s ease, stroke 0.2s ease; flex-shrink: 0;
}
.footer-link:hover { color: #60A5FA; transform: translateX(4px); }
.footer-link:hover svg { stroke: #93C5FD; transform: translateX(2px); }
.footer-socials { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 6px; }
.footer-social-btn {
  width: 38px; height: 38px;
  display: inline-flex; align-items: center; justify-content: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  color: #94A3B8;
  transition: all 0.25s ease;
  text-decoration: none;
}
.footer-social-btn:hover { transform: translateY(-3px); box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3); }
.footer-social-btn[title*='YouTube']:hover { background: #FF0000; border-color: #FF0000; color: #FFFFFF; }
.footer-social-btn[title*='Instagram']:hover { background: linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888); border-color: transparent; color: #FFFFFF; }
.footer-social-btn[title*='Facebook']:hover { background: #1877F2; border-color: #1877F2; color: #FFFFFF; }
.footer-social-btn[title*='Twitter']:hover, .footer-social-btn[title*='X']:hover { background: #111111; border-color: #333333; color: #FFFFFF; }
.footer-social-btn[title*='LinkedIn']:hover { background: #0A66C2; border-color: #0A66C2; color: #FFFFFF; }
.footer-social-btn svg { width: 16px; height: 16px; fill: currentColor; }

/* Newsletter Card Column */
.footer-newsletter-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
}
.footer-newsletter-card p { font-size: 0.82rem; color: #94A3B8; line-height: 1.5; margin-bottom: 12px; }
.footer-newsletter-form { display: flex; flex-direction: column; gap: 10px; }
.footer-newsletter-input {
  width: 100%; padding: 10px 14px; border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12); background: rgba(15, 23, 42, 0.6);
  color: #FFFFFF; font-size: 0.84rem; outline: none; transition: all 0.2s ease;
}
.footer-newsletter-input::placeholder { color: #64748B; }
.footer-newsletter-input:focus {
  border-color: #3B82F6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25); background: rgba(15, 23, 42, 0.9);
}
.footer-newsletter-btn {
  width: 100%; padding: 11px 16px;
  background: linear-gradient(135deg, #2563EB 0%, #7C3AED 100%);
  color: #FFFFFF; border: none; border-radius: 8px;
  font-weight: 600; font-size: 0.84rem; cursor: pointer;
  transition: all 0.25s ease; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
}
.footer-newsletter-btn:hover { transform: translateY(-1px); box-shadow: 0 6px 18px rgba(37, 99, 235, 0.35); }
.footer-newsletter-note { font-size: 0.73rem; color: #94A3B8; margin-top: 8px; display: flex; align-items: center; gap: 5px; }

/* Footer Bottom Bar */
.footer-bottom {
  padding: 24px 0;
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 12px;
  font-size: 0.8rem; color: #94A3B8;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.footer-copyright { color: #94A3B8; font-size: 0.8rem; }
.footer-bottom-links { display: flex; align-items: center; gap: 16px; }
.footer-bottom-link { color: #94A3B8; font-size: 0.8rem; text-decoration: none; transition: color 0.2s ease; }
.footer-bottom-link:hover { color: #60A5FA; }

/* Blogger Attribution Override */
.footer-attr-area { display: inline-flex; align-items: center; }
.footer-attr-area .widget.Attribution { margin: 0; padding: 0; background: none; border: none; }
.footer-attr-area .widget-content { font-size: 0.8rem; color: #94A3B8; margin: 0; padding: 0; border: none; background: none; }
.footer-attr-area .blogger a { color: #94A3B8; font-size: 0.8rem; text-decoration: none; transition: color 0.2s ease; display: inline-flex; align-items: center; }
.footer-attr-area .blogger a:hover { color: #60A5FA; }
.footer-attr-area svg, .footer-attr-area .flatBloggerIcon, .footer-attr-area img { display: none !important; }

/* ============================================================
   18. FADE-IN ANIMATION
============================================================ */
.fade-in-ready { opacity: 0; transform: translateY(16px); transition: opacity 0.5s ease, transform 0.5s ease; }
.fade-in-ready.visible { opacity: 1; transform: translateY(0); }

/* ============================================================
   19. RESPONSIVE BREAKPOINTS
============================================================ */
@media (min-width: 1200px) {
  .home-layout {
    width: calc(100% - 100px);
    max-width: 1600px;
    margin: 0 auto;
  }
  .home-main-grid {
    grid-template-columns: minmax(0, 1fr) 320px;
    gap: 28px;
  }
  .home-main-grid .posts-grid,
  .latest-posts-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 22px;
  }
}

@media (min-width: 769px) and (max-width: 1199px) {
  .home-layout {
    width: calc(100% - 48px);
    margin: 0 auto;
  }
  .home-main-grid {
    grid-template-columns: minmax(0, 1fr) 280px;
    gap: 22px;
  }
  .home-main-grid .posts-grid,
  .latest-posts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
  }
  .home-sidebar {
    display: block !important;
  }
}

@media (max-width: 1100px) {
  .nav-menu { gap: 1.25rem; }
  .nav-menu-link { font-size: 0.82rem; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
}
@media (max-width: 900px) {
  .nav-menu { display: none; }
  .nav-hamburger { display: flex; }
  .main-grid { grid-template-columns: 1fr; }
  .single-post-grid { grid-template-columns: 1fr; }
  body:not(.home-layout) .sidebar-area { display: none; }
  .mag-inner { grid-template-columns: 1fr; }
  .mag-small-group { display: grid; grid-template-columns: repeat(2,1fr); }
  .hero-mini-grid { grid-template-columns: repeat(2,1fr); }
  .newsletter-inner { grid-template-columns: 1fr; }
  .newsletter-form-col { width: 100%; }
  .newsletter-form-group { min-width: unset; }
  .post-nav { grid-template-columns: 1fr; }
  .post-nav-next { text-align: left; justify-content: flex-start; }
}
@media (max-width: 768px) {
  .home-layout {
    width: calc(100% - 32px);
    margin: 0 auto;
  }
  .home-main-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .home-main-grid .posts-grid,
  .latest-posts-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .home-sidebar {
    display: block !important;
    width: 100%;
  }
  .hero-inner { grid-template-columns: 1fr; min-height: unset; }
  .hero-content { max-width: 100%; }
}
@media (max-width: 640px) {
  .hero-section { min-height: 500px; }
  .hero-inner { padding: 2.5rem 0; min-height: unset; }
  .hero-title { font-size: 1.5rem; }
  .hero-mini-grid { grid-template-columns: 1fr; }
  .posts-grid { grid-template-columns: 1fr; }
  .categories-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .mag-small-group { grid-template-columns: 1fr; }
  .newsletter-inner { padding: 2rem 1.5rem; }
  .newsletter-heading { font-size: 1.4rem; }
  .post-header-section { padding: 1.5rem 1.5rem 0; }
  .post-content { padding: 1rem 1.5rem 1.5rem; line-height: 1.6; }
  .share-bar, .author-bio, .related-section, .post-nav { margin-left: 1.5rem; margin-right: 1.5rem; }
  .post-comments { padding: 1.5rem; }
  .post-main-title { font-size: 1.4rem; }
}
@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .nav-inner { gap: 0.35rem; }
  .nav-logo-text { font-size: 1.1rem; }
  .nav-logo-img { width: 40px; height: 40px; }
  .nav-logo { gap: 8px; }
  .nav-subscribe-btn { padding: 0.4rem 0.7rem; font-size: 0.72rem; }
  .nav-subscribe-btn svg { display: none; }
  .nav-icon-btn { width: 34px; height: 34px; }
  .nav-hamburger { width: 34px; height: 34px; }
  .hero-section { min-height: 480px; }
  .hero-inner { padding: 2rem 0; min-height: unset; }
  .hero-title { font-size: 1.25rem; }
  .hero-excerpt { font-size: 0.85rem; -webkit-line-clamp: 2; }
  .hero-category-badge { font-size: 0.6rem; padding: 0.25rem 0.7rem; }
  .hero-meta { gap: 0.5rem; }
  .hero-author { font-size: 0.72rem; }
  .hero-author-avatar { width: 24px; height: 24px; }
  .hero-date, .hero-readtime { font-size: 0.72rem; }
  .hero-cta { font-size: 0.78rem; padding: 0.6rem 1.25rem; }
  .hero-mini-section { margin-top: -32px; padding: 0 0 1.5rem; }
  .mini-card { padding: 0.5rem; gap: 0.65rem; }
  .mini-card-number { font-size: 1.5rem; width: 28px; }
  .mini-card-img { width: 56px; height: 48px; }
  .mini-card-title { font-size: 0.75rem; }
  .mini-card-date { font-size: 0.6rem; }
  .trending-section { padding: 1.25rem 0 1.5rem; }
  .trend-cat-card { padding: 0.65rem 0.85rem; min-width: 76px; }
  .trend-cat-name { font-size: 0.65rem; }
  .trend-cat-icon { width: 34px; height: 34px; font-size: 1.1rem; }
  .section-title { font-size: 1rem; }
  .section-subtitle { font-size: 0.72rem; }
  .section-view-all { font-size: 0.7rem; padding: 0.3rem 0.65rem; }
  .main-layout { padding: 1.5rem 0 2rem; }
  .posts-grid { gap: 1rem; }
  .post-card-body { padding: 0.85rem; }
  .post-card-title { font-size: 0.85rem; }
  .post-card-excerpt { font-size: 0.78rem; -webkit-line-clamp: 2; }
  .post-card-footer { padding-top: 0.6rem; }
  .post-card-meta { font-size: 0.68rem; }
  .post-card-category { font-size: 0.55rem; padding: 0.2rem 0.5rem; top: 0.5rem; left: 0.5rem; }
  .pagination { gap: 0.35rem; margin-top: 1.5rem; }
  .pagination-btn { min-width: 36px; height: 36px; padding: 0 0.65rem; font-size: 0.75rem; }
  .pagination-prev,
  .pagination-next { padding: 0 0.75rem; }
  .pagination-ellipsis { min-width: 20px; height: 36px; font-size: 0.85rem; }
  .newsletter-inner { padding: 1.5rem 1rem; gap: 1.5rem; }
  .newsletter-heading { font-size: 1.15rem; }
  .newsletter-subtext { font-size: 0.8rem; }
  .newsletter-eyebrow { font-size: 0.6rem; }
  .newsletter-form-group { gap: 0.5rem; }
  .newsletter-form-input { padding: 0.65rem 1rem; font-size: 0.8rem; }
  .newsletter-form-btn { padding: 0.65rem 1rem; font-size: 0.8rem; }
  .magazine-block { margin-bottom: 1.5rem; }
  .mag-inner { gap: 1rem; }
  .mag-large-body { padding: 1rem; }
  .mag-large-title { font-size: 0.95rem; }
  .mag-large-cat { font-size: 0.55rem; }
  .mag-large-excerpt { font-size: 0.78rem; -webkit-line-clamp: 2; }
  .mag-small-body { padding: 0.65rem 0.75rem; }
  .mag-small-title { font-size: 0.75rem; }
  .mag-small-img { width: 72px; }
  .single-post-wrapper { padding: 0 0 2rem; }
  .post-body-card { border-radius: var(--radius-lg); }
  .post-header-section { padding: 1.25rem 1rem 0; }
  .post-main-title { font-size: 1.2rem; }
  .post-breadcrumb { font-size: 0.65rem; margin-bottom: 0.75rem; }
  .post-label-tag { font-size: 0.55rem; padding: 0.2rem 0.55rem; }
  .post-author-row { gap: 0.65rem; padding-bottom: 1rem; }
  .post-author-avatar { width: 34px; height: 34px; }
  .post-author-name { font-size: 0.78rem; }
  .post-author-meta { font-size: 0.68rem; gap: 0.35rem; }
  .post-content { padding: 0.75rem 1rem 1.25rem; font-size: 0.92rem; line-height: 1.6; }
  .post-content p { margin-bottom: 0.7rem; }
  .post-content .separator,
  .post-content img { margin-top: 0.65rem; margin-bottom: 0.65rem; }
  .post-content h2 { font-size: 1.15rem; margin: 1.25rem 0 0.625rem; }
  .post-content h3 { font-size: 1rem; margin: 1rem 0 0.5rem; }
  .share-bar, .author-bio { margin: 0 1rem 1.5rem; padding: 0.85rem; }
  .share-bar { flex-direction: column; align-items: flex-start; gap: 0.65rem; }
  .share-bar-label { font-size: 0.72rem; }
  .share-btn { width: 30px; height: 30px; }
  .author-bio { flex-direction: column; align-items: center; text-align: center; }
  .author-bio-avatar { width: 48px; height: 48px; }
  .author-bio-name { font-size: 0.85rem; }
  .author-bio-text { font-size: 0.78rem; }
  .related-section { margin: 0 1rem 1.5rem; }
  .related-title { font-size: 0.88rem; margin-bottom: 0.85rem; }
  .post-nav { margin: 0 1rem 1.5rem; gap: 0.65rem; }
  .post-nav-btn { padding: 0.75rem; }
  .post-nav-ptitle { font-size: 0.72rem; }
  .post-comments { padding: 1.25rem 1rem; }
  .footer-top { padding: 36px 0 24px; }
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
  .footer-col-brand { align-items: center; text-align: center; }
  .footer-logo-wrapper { justify-content: center; }
  .footer-socials { justify-content: center; }
  .footer-logo-text { font-size: 1.25rem; }
  .footer-about { font-size: 0.82rem; max-width: 480px; margin-left: auto; margin-right: auto; }
  .footer-bottom { flex-direction: column; text-align: center; gap: 12px; font-size: 0.78rem; }
  .footer-bottom-links { flex-wrap: wrap; justify-content: center; gap: 12px; }
  .search-overlay { padding-top: 80px; }
  .search-overlay-label { font-size: 0.68rem; margin-bottom: 1rem; }
  .search-overlay-input { font-size: 1.2rem; }
  .search-overlay-btn { font-size: 0.75rem; padding: 0.45rem 0.85rem; }
  .search-overlay-close { top: 1rem; right: 1rem; font-size: 1.5rem; }
  .mobile-drawer { width: 280px; }
  .drawer-header { padding: 1rem 1.25rem; }
  .drawer-logo { font-size: 0.95rem; }
  .drawer-nav-link { font-size: 0.82rem; padding: 0.55rem 0.85rem; }
  .empty-state { padding: 2.5rem 1rem; }
  .empty-state h3 { font-size: 1rem; }
  .empty-state p { font-size: 0.8rem; }
}
@media (max-width: 400px) {
  .container { padding: 0 0.75rem; }
  .nav-logo-text { font-size: 0.95rem; }
  .nav-logo-img { width: 32px; height: 32px; }
  .nav-logo { gap: 6px; }
  .nav-subscribe-btn { padding: 0.3rem 0.55rem; font-size: 0.65rem; }
  .nav-icon-btn { width: 30px; height: 30px; }
  .nav-icon-btn svg { width: 17px; height: 17px; }
  .nav-hamburger { width: 30px; height: 30px; }
  .nav-hamburger span { width: 15px; }
  .hero-section { min-height: 400px; }
  .hero-inner { padding: 1.5rem 0; }
  .hero-title { font-size: 1.1rem; }
  .hero-excerpt { font-size: 0.78rem; }
  .hero-cta { font-size: 0.72rem; padding: 0.5rem 1rem; }
  .hero-cta svg { width: 13px; height: 13px; }
  .mini-card { padding: 0.4rem; gap: 0.5rem; }
  .mini-card-number { font-size: 1.2rem; width: 22px; }
  .mini-card-img { width: 48px; height: 40px; }
  .mini-card-title { font-size: 0.7rem; }
  .trend-cat-card { padding: 0.5rem 0.65rem; min-width: 66px; }
  .trend-cat-name { font-size: 0.6rem; }
  .trend-cat-icon { width: 28px; height: 28px; font-size: 0.95rem; }
  .posts-grid { gap: 0.75rem; }
  .post-card-body { padding: 0.65rem; gap: 0.5rem; }
  .post-card-title { font-size: 0.78rem; }
  .post-card-excerpt { font-size: 0.72rem; }
  .post-card-meta { font-size: 0.62rem; gap: 0.35rem; }
  .post-card-readmore { font-size: 0.68rem; }
  .section-title { font-size: 0.88rem; }
  .newsletter-heading { font-size: 1rem; }
  .newsletter-subtext { font-size: 0.75rem; }
  .newsletter-form-input { padding: 0.55rem 0.85rem; font-size: 0.75rem; }
  .newsletter-form-btn { padding: 0.55rem 0.85rem; font-size: 0.75rem; }
  .mag-large-title { font-size: 0.85rem; }
  .mag-large-body { padding: 0.75rem; gap: 0.5rem; }
  .mag-large-excerpt { font-size: 0.72rem; }
  .mag-small-body { padding: 0.5rem 0.6rem; }
  .mag-small-title { font-size: 0.7rem; }
  .mag-small-cat { font-size: 0.5rem; }
  .mag-small-img { width: 60px; }
  .post-main-title { font-size: 1.05rem; }
  .post-content { font-size: 0.85rem; padding: 0.5rem 0.75rem 1rem; }
  .post-content h2 { font-size: 1.05rem; }
  .post-content h3 { font-size: 0.92rem; }
  .post-header-section { padding: 1rem 0.75rem 0; }
  .share-bar, .author-bio { margin-left: 0.75rem; margin-right: 0.75rem; padding: 0.65rem; }
  .related-section { margin: 0 0.75rem 1.25rem; }
  .post-nav { margin: 0 0.75rem 1.25rem; }
  .post-comments { padding: 1rem 0.75rem; }
  .post-breadcrumb { font-size: 0.6rem; }
  .post-label-tag { font-size: 0.5rem; padding: 0.15rem 0.45rem; }
  .post-author-name { font-size: 0.72rem; }
  .post-author-meta { font-size: 0.62rem; }
  .footer-top { padding: 28px 0 20px; }
  .footer-grid { gap: 20px; }
  .footer-logo-text { font-size: 1.15rem; }
  .pagination-btn { min-width: 32px; height: 32px; padding: 0 0.5rem; font-size: 0.7rem; }
  .pagination-prev,
  .pagination-next { padding: 0 0.6rem; }
  .pagination-ellipsis { min-width: 16px; height: 32px; font-size: 0.75rem; }
  .mobile-drawer { width: 260px; }
}
/* ============================================================
   STICKY LEFT TABLE OF CONTENTS & POST ALIGNMENT
============================================================ */
.vtj-toc-rail {
  display: block;
  align-self: stretch;
  position: relative;
  width: 180px;
  min-width: 0;
  height: auto;
  min-height: 100%;
  overflow: visible;
  margin: 0;
  padding: 0;
}
.vtj-toc {
  position: -webkit-sticky;
  position: sticky;
  top: calc(var(--nav-height) + 20px);
  width: 100%;
  max-height: calc(100vh - var(--nav-height) - 40px);
  overflow-y: auto;
  overscroll-behavior: contain;
  align-self: start;
  z-index: 20;
  padding: 0.75rem 0.5rem;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.vtj-toc::-webkit-scrollbar { width: 4px; }
.vtj-toc::-webkit-scrollbar-thumb { background: var(--border); border-radius: 10px; }

.vtj-toc-heading {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 1.25rem;
  color: var(--text-primary);
}
.vtj-toc-heading svg {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  color: var(--primary);
}
.vtj-toc-list {
  position: relative;
  padding-left: 1rem;
}
.vtj-toc-list::before {
  content: "";
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 4px;
  width: 3px;
  background: linear-gradient(to bottom, rgba(37,99,235,0.1), rgba(124,58,237,0.1));
  border-radius: 4px;
}
html.dark .vtj-toc-list::before {
  background: linear-gradient(to bottom, rgba(96,165,250,0.1), rgba(167,139,250,0.1));
}
.vtj-toc-link {
  position: relative;
  display: block;
  padding: 0.4rem 0 0.4rem 0.7rem;
  font-size: 0.75rem;
  line-height: 1.4;
  color: var(--text-muted);
  transition: all 0.3s ease;
  text-decoration: none;
  border-radius: var(--radius-sm);
  margin-bottom: 0.25rem;
  overflow-wrap: anywhere;
}
.vtj-toc-link::before {
  content: "";
  position: absolute;
  left: -1rem;
  top: 50%;
  transform: translateY(-50%) scale(0.8);
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: 2px solid var(--bg-card);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 0 0 2px transparent;
}
html.dark .vtj-toc-link::before {
  background: var(--text-faint);
  border-color: var(--bg-elevated);
}
.vtj-toc-link:hover { 
  color: var(--primary);
  background: rgba(37,99,235,0.04);
  padding-left: 1rem;
}
html.dark .vtj-toc-link:hover {
  background: rgba(96,165,250,0.05);
}
.vtj-toc-link.active { 
  color: var(--secondary); 
  font-weight: 600; 
  background: rgba(124,58,237,0.06);
  padding-left: 1rem;
}
html.dark .vtj-toc-link.active {
  color: #A78BFA;
  background: rgba(167,139,250,0.1);
}
.vtj-toc-link.active::before { 
  background: var(--secondary); 
  border-color: var(--bg-card);
  transform: translateY(-50%) scale(1.1); 
  box-shadow: 0 0 0 3px rgba(124,58,237,0.15);
}
html.dark .vtj-toc-link.active::before {
  background: #A78BFA;
  border-color: var(--bg-elevated);
  box-shadow: 0 0 0 3px rgba(167,139,250,0.2);
}
.vtj-toc-link.level-h3 { padding-left: 1.2rem; font-size: 0.7rem; }

.post-content h2, .post-content h3 { scroll-margin-top: 100px; }

/* Wide Desktop Grid (>= 1600px) */
@media screen and (min-width: 1600px) {
  .container.vtj-post-container { max-width: 1640px; overflow: visible; }
  .main-grid.vtj-post-wide-layout {
    display: grid;
    grid-template-columns: 180px minmax(760px, 1fr) 300px;
    column-gap: 24px;
    align-items: stretch;
    overflow: visible;
    width: calc(100% - 32px);
    max-width: 1640px;
    margin: 0 auto;
    padding: 2.5rem 16px 3rem;
  }
  .content-area.vtj-post-main-column, .sidebar-area {
    min-width: 0; margin-top: 0; align-self: start;
  }
  .vtj-toc-rail { display: block; width: 180px; align-self: stretch; }
  .content-area.vtj-post-main-column { width: 100%; max-width: none; }
  .sidebar-area { width: 300px; }
}

/* Below 1600px */
@media screen and (max-width: 1599px) {
  .main-grid.vtj-post-wide-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 2.5rem;
    align-items: start;
    width: 100%;
  }
  .vtj-toc-rail { display: none !important; }
}

/* Tablet & Mobile (<= 1024px) */
@media screen and (max-width: 1024px) {
  .main-grid.vtj-post-wide-layout { grid-template-columns: 1fr; }
  .sidebar-area { width: 100%; }
}

/* ============================================================
   FAQ ACCORDION (vtj-faq-*)
============================================================ */
.vtj-faq-section {
  width: 100%;
  margin: 1.25rem 0;
}

.vtj-faq-item {
  margin-bottom: 0.8rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-card);
  overflow: hidden;
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    transform 0.25s ease;
}

.vtj-faq-item:hover {
  border-color: rgba(37, 99, 235, 0.35);
}

.vtj-faq-item.active {
  border-color: rgba(37, 99, 235, 0.45);
  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.08);
}

.vtj-faq-question {
  width: 100%;
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.15rem;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  font-family: var(--font-heading);
  font-size: 0.98rem;
  font-weight: 700;
  line-height: 1.45;
  text-align: left;
  cursor: pointer;
  transition:
    background 0.25s ease,
    color 0.25s ease;
}

.vtj-faq-question:hover {
  background: rgba(37, 99, 235, 0.045);
}

.vtj-faq-question:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
}

.vtj-faq-icon {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(37, 99, 235, 0.1);
  color: var(--primary);
  font-family: Arial, sans-serif;
  font-size: 1.35rem;
  font-weight: 500;
  line-height: 1;
  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease;
}

.vtj-faq-item.active .vtj-faq-icon {
  transform: rotate(45deg);
  background: var(--gradient-main);
  color: #ffffff;
}

.vtj-faq-answer {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  visibility: hidden;
  transition:
    grid-template-rows 0.35s ease,
    opacity 0.25s ease,
    visibility 0.35s ease;
}

.vtj-faq-item.active .vtj-faq-answer {
  grid-template-rows: 1fr;
  opacity: 1;
  visibility: visible;
}

.vtj-faq-answer-inner {
  min-height: 0;
  overflow: hidden;
  padding: 0 1.15rem;
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: 0.94rem;
  line-height: 1.75;
  transition: padding 0.35s ease;
}

.vtj-faq-item.active .vtj-faq-answer-inner {
  padding: 0 1.15rem 1.15rem;
}

html.dark .vtj-faq-item {
  background: var(--bg-elevated);
  border-color: var(--border);
}

html.dark .vtj-faq-question:hover {
  background: rgba(96, 165, 250, 0.06);
}

html.dark .vtj-faq-item.active {
  border-color: rgba(96, 165, 250, 0.4);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);
}

html.dark .vtj-faq-icon {
  background: rgba(96, 165, 250, 0.12);
  color: #60a5fa;
}

html.dark .vtj-faq-item.active .vtj-faq-icon {
  color: #ffffff;
}

@media (max-width: 600px) {
  .vtj-faq-item {
    border-radius: 10px;
    margin-bottom: 0.7rem;
  }

  .vtj-faq-question {
    min-height: 54px;
    padding: 0.9rem 0.95rem;
    gap: 0.75rem;
    font-size: 0.9rem;
  }

  .vtj-faq-icon {
    width: 28px;
    height: 28px;
    flex-basis: 28px;
    font-size: 1.2rem;
  }

  .vtj-faq-answer-inner {
    padding: 0 0.95rem;
    font-size: 0.88rem;
    line-height: 1.65;
  }

  .vtj-faq-item.active .vtj-faq-answer-inner {
    padding: 0 0.95rem 1rem;
  }
}

body.script:
//
  (function(){
    var FALLBACK_IMG = 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=70';
    var FALLBACK_HERO = 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1920&auto=format&fit=crop&q=80';

    /* ---- Utility ---- */
    function getThumb(entry, size) {
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        return entry.media$thumbnail.url
          .replace('/s72-c/', '/w' + size + '-h' + size + '-c-rw/')
          .replace(/\/s\d+(-c)?\//, '/w' + size + '-h' + size + '-c-rw/')
          .replace(/\/w\d+-h\d+(-c)?\//, '/w' + size + '-h' + size + '-c-rw/')
          .replace(/=s\d+.*$/, '=w' + size + '-h' + size + '-c-rw')
          .replace(/=w\d+-h\d+.*$/, '=w' + size + '-h' + size + '-c-rw');
      }
      return FALLBACK_IMG;
    }
    function getUrl(entry) {
      if (!entry.link) return '#';
      for (var i = 0; entry.link.length > i; i++) {
        if (entry.link[i].rel === 'alternate') return entry.link[i].href;
      }
      return '#';
    }
    function getCategory(entry) {
      if (entry.category && entry.category.length > 0) return entry.category[0].term;
      return 'Technology';
    }
    function formatDate(dateStr) {
      try {
        var d = new Date(dateStr);
        return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      } catch(e) { return ''; }
    }
    function calcReadTime(text) {
      var words = text ? text.trim().split(/\s+/).length : 200;
      return Math.max(1, Math.round(words / 220));
    }

    /* ---- Theme Toggle ---- */
    function toggleTheme() {
      var isDark = document.documentElement.classList.toggle('dark');
      localStorage.setItem('tvh-theme', isDark ? 'dark' : 'light');
    }
    var navThemeBtn = document.getElementById('nav-theme-btn');
    if (navThemeBtn) navThemeBtn.addEventListener('click', toggleTheme);

    /* ---- Search Overlay ---- */
    var overlay = document.getElementById('search-overlay');
    var overlayClose = document.getElementById('search-overlay-close');
    var overlayInput = document.getElementById('search-overlay-input');
    function openSearch() {
      if (overlay) { overlay.classList.add('active'); if (overlayInput) overlayInput.focus(); }
    }
    function closeSearch() { if (overlay) overlay.classList.remove('active'); }
    var navSearchBtn = document.getElementById('nav-search-btn');
    if (navSearchBtn) navSearchBtn.addEventListener('click', function(e) { e.preventDefault(); openSearch(); });
    if (overlayClose) overlayClose.addEventListener('click', closeSearch);
    document.addEventListener('keydown', function(e) { if (e.key === 'Escape') { closeSearch(); closeDrawer(); } });

    /* ---- Mobile Drawer ---- */
    var drawer = document.getElementById('mobile-drawer');
    var drawerOverlay = document.getElementById('drawer-overlay');
    var drawerClose = document.getElementById('drawer-close');
    var hamburger = document.getElementById('nav-hamburger');
    function openDrawer() { if (drawer) drawer.classList.add('active'); if (drawerOverlay) drawerOverlay.classList.add('active'); }
    function closeDrawer() { if (drawer) drawer.classList.remove('active'); if (drawerOverlay) drawerOverlay.classList.remove('active'); }
    if (hamburger) hamburger.addEventListener('click', openDrawer);
    if (drawerClose) drawerClose.addEventListener('click', closeDrawer);
    if (drawerOverlay) drawerOverlay.addEventListener('click', closeDrawer);

    /* ---- Sticky Header Scroll ---- */
    var siteHeader = document.getElementById('site-header');
    window.addEventListener('scroll', function() {
      if (!siteHeader) return;
      if (100 > window.scrollY) { siteHeader.classList.remove('scrolled'); }
      else { siteHeader.classList.add('scrolled'); }
    }, { passive: true });

    /* ---- Sync Logo Images ---- */
    function extractUrl(str) {
      var m = str.match(/url\(["']?([^"')]+)["']?\)/);
      return m ? m[1] : null;
    }
    function setLogoSrc(src) {
      if (!src) return;
      var h = document.getElementById('header-logo-img');
      var d = document.getElementById('drawer-logo-img');
      var f = document.getElementById('footer-logo-img');
      var dt = document.getElementById('drawer-logo-text');
      var ft = document.getElementById('footer-logo-text');
      if (h) { h.setAttribute('src', src); h.style.display = ''; }
      if (d) { d.src = src; d.style.display = 'block'; }
      if (f) { f.src = src; f.style.display = 'block'; }
      if (dt) dt.style.display = 'none';
      if (ft) ft.style.display = 'block';
      var ab = document.getElementById('about-sidebar-logo');
      if (ab && !ab.querySelector('img')) {
        var aimg = document.createElement('img');
        aimg.src = src;
        aimg.alt = 'Vicky Tech Journal';
        aimg.width = 120;
        aimg.height = 120;
        aimg.loading = 'lazy';
        ab.appendChild(aimg);
      }
      var ytAv = document.getElementById('social-avatar-yt');
      if (ytAv && !ytAv.querySelector('img')) {
        var ytImg = document.createElement('img');
        ytImg.src = src;
        ytImg.alt = 'Vicky Tech Journal';
        ytImg.width = 72;
        ytImg.height = 72;
        ytImg.loading = 'lazy';
        ytAv.appendChild(ytImg);
      }
      var igAv = document.getElementById('social-avatar-ig');
      if (igAv && !igAv.querySelector('img')) {
        var igImg = document.createElement('img');
        igImg.src = src;
        igImg.alt = 'Vicky Tech Journal';
        igImg.width = 72;
        igImg.height = 72;
        igImg.loading = 'lazy';
        igAv.appendChild(igImg);
      }

    }
    function resolveLogo() {
      var h = document.getElementById('header-logo-img');
      if (!h) return;
      var src = h.getAttribute('src');
      if (!src || src.indexOf('/') < 0) {
        var els = document.querySelectorAll('.header-logo-area, .header-widget');
        for (var i = 0; i < els.length; i++) {
          var bg = window.getComputedStyle(els[i]).backgroundImage;
          if (bg && bg !== 'none') {
            var url = extractUrl(bg);
            if (url) { setLogoSrc(url); return; }
          }
        }
        h.style.display = 'none';
      } else {
        setLogoSrc(src);
      }
    }
    resolveLogo();
    setTimeout(resolveLogo, 500);

    /* ---- Subscribe Dropdown ---- */
    (function(){
      var btn = document.getElementById('nav-subscribe-btn');
      var dd  = document.getElementById('nav-subscribe-dropdown');
      if (!btn || !dd) return;
      btn.addEventListener('click', function(e){
        e.stopPropagation();
        dd.classList.toggle('open');
      });
      document.addEventListener('click', function(e){
        if (!dd.contains(e.target) && !btn.contains(e.target)) {
          dd.classList.remove('open');
        }
      });
    })();

    /* ---- Fade-in on Scroll ---- */
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
          if (entry.isIntersecting) { entry.target.classList.add('visible'); io.unobserve(entry.target); }
        });
      }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
      document.querySelectorAll('.fade-in-ready').forEach(function(el) { io.observe(el); });
    } else {
      document.querySelectorAll('.fade-in-ready').forEach(function(el) { el.classList.add('visible'); });
    }

    /* ---- Reading Time (card estimates) ---- */
    document.querySelectorAll('.post-read-time-val').forEach(function(el) {
      var card = el.closest('.post-card');
      if (!card) return;
      var excerpt = card.querySelector('.post-card-excerpt');
      if (excerpt) {
        var words = excerpt.textContent.trim().split(/\s+/).length * 8;
        el.textContent = Math.max(2, Math.round(words / 220)) + ' min';
      }
    });

    /* ====================================================
       HOMEPAGE-ONLY DYNAMIC CONTENT
    ==================================================== */
    var isHomepage = document.getElementById("vtj-featured-slider-section") !== null;
    var BLOG_URL = document.body.getAttribute("data-url") || "";
    if (!BLOG_URL || BLOG_URL.indexOf("blogger.com") !== -1) {
      BLOG_URL = "/";
    } else if (BLOG_URL.charAt(BLOG_URL.length - 1) !== "/") {
      BLOG_URL += "/";
    }

    if (!isHomepage) {
      initSinglePost();
      if (window.location.pathname.indexOf('/p/articles.html') !== -1) {
        loadArticlesPage();
      }
      return;
    }

    /* ---- High-Resolution Image Helper ---- */
    function getFirstImgSrc(entry) {
      var content = (entry.content && entry.content.$t) || '';
      if (content) {
        var cm = content.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (cm && cm[1] && cm[1].indexOf('data:') !== 0) {
          return cm[1]
            .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
            .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
            .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
            .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
            .replace(/=s\d+.*$/, '=w800-h450-c-rw');
        }
      }
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        return entry.media$thumbnail.url
          .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
          .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
          .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
          .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
          .replace(/=s\d+.*$/, '=w800-h450-c-rw');
      }
      var summary = (entry.summary && entry.summary.$t) || '';
      if (summary) {
        var sm = summary.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (sm && sm[1]) return sm[1];
      }
      return FALLBACK_IMG;
    }

    function cleanSummary(text, length) {
      if (!text) return '';
      var temp = document.createElement('div');
      temp.innerHTML = text;
      var clean = temp.textContent || temp.innerText || '';
      clean = clean.replace(/\s+/g, ' ').trim();
      if (clean.length > length) {
        clean = clean.substring(0, length).trim() + '...';
      }
      return clean;
    }

    function getReadingTime(entry) {
      var text = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || '';
      var cleanText = text.replace(/<[^>]*>/g, '').trim();
      var words = cleanText.split(/\s+/).length;
      if (entry.content) {
        return Math.max(1, Math.round(words / 220));
      } else {
        return Math.max(2, Math.round((words * 8) / 220));
      }
    }

    /* ---- Featured Post Slider ---- */
    var sliderEntries = [];
    var sliderCurrent = 0;
    var sliderTimer = null;
    var sliderInterval = 4000;
    var sliderIsPaused = false;
    var DEFAULT_FEATURED_IMAGE = "https://images.unsplash.com/photo-1677442136019-21780efad99a?w=800&auto=format&fit=crop&q=80";

    function escapeHtml(str) {
      return (str || '')
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    }

    function getHighQualityImage(url) {
      if (!url) return DEFAULT_FEATURED_IMAGE;

      return url
        .replace(/\/s72-c\//, "/w800-h450-c-rw/")
        .replace(/\/s100-c\//, "/w800-h450-c-rw/")
        .replace(/\/s150-c\//, "/w800-h450-c-rw/")
        .replace(/\/s[0-9]+(-c)?\//, "/w800-h450-c-rw/")
        .replace(/=s[0-9]+(-c)?/, "=w800-h450-c-rw")
        .replace(/\/w[0-9]+-h[0-9]+(-c)?\//, "/w800-h450-c-rw/")
        .replace(/\/w[0-9]+-h[0-9]+-p-k-no-nu\//, "/w800-h450-c-rw/");
    }

    function loadHeroSlider() {
      if (!document.getElementById("vtj-featured-slider-container")) return;
      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=10&callback=vtjHeroSliderCb";
      document.body.appendChild(s);
      setTimeout(function() {
        if (sliderEntries.length === 0) renderHeroSliderFallback();
      }, 5000);
    }

    window.vtjHeroSliderCb = function(data) {
      var entries = data.feed && data.feed.entry ? data.feed.entry : [];
      if (entries.length === 0) { renderHeroSliderFallback(); return; }
      sliderEntries = entries;
      renderHeroSlider(entries);
    };

    function renderHeroSliderFallback() {
      var mockups = [
        { title: "Top 10 AI Tools to Boost Your Daily Productivity", cat: "AI Tools", img: "https://images.unsplash.com/photo-1677442136019-21780efad99a?w=800&auto=format&fit=crop&q=80", summary: "Discover the best artificial intelligence tools that can help automate your workflow, write code faster, and design premium assets.", date: "Jul 20, 2026", rt: 5 },
        { title: "Essential Software Guides Every Student Should Read", cat: "Software", img: "https://images.unsplash.com/photo-1501504905252-473c47e087f8?w=800&auto=format&fit=crop&q=80", summary: "Learn about the most useful open source software, desktop apps, and coding editors for college and high school students.", date: "Jul 19, 2026", rt: 4 },
        { title: "How to Secure Your Digital Footprint Online in 2026", cat: "Cyber Security", img: "https://images.unsplash.com/photo-1563986768609-322da13575f3?w=800&auto=format&fit=crop&q=80", summary: "A comprehensive guide on online privacy, securing password managers, browser extensions, and routing traffic securely.", date: "Jul 18, 2026", rt: 6 },
        { title: "15 Chrome Extensions That Save Hours of Coding Work", cat: "Extensions", img: "https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800&auto=format&fit=crop&q=80", summary: "A handpicked list of extensions for developer tools, color picking, CSS inspection, and console formatting.", date: "Jul 18, 2026", rt: 5 }
      ];
      var mockEntries = mockups.map(function(m) {
        return {
          title: { $t: m.title },
          summary: { $t: m.summary },
          published: { $t: new Date(m.date).toISOString() },
          category: [{ term: m.cat }],
          link: [{ rel: "alternate", href: "#" }],
          media$thumbnail: { url: m.img }
        };
      });
      sliderEntries = mockEntries;
      renderHeroSlider(mockEntries);
    }

    function renderHeroSlider(entries) {
      var container = document.getElementById("vtj-featured-slider-container");
      if (!container) return;

      var track = document.createElement("div");
      track.className = "featured-slider-track";
      track.id = "vtj-featured-slider-track";
      track.setAttribute("aria-live", "polite");

      var dotsHtml = "";
      for (var i = 0; i < entries.length; i++) {
        var slide = document.createElement("div");
        slide.className = "featured-slide" + (i === 0 ? " active" : "");
        slide.setAttribute("role", "group");
        slide.setAttribute("aria-roledescription", "slide");
        slide.setAttribute("aria-label", "Slide " + (i + 1) + " of " + entries.length);
        slide.innerHTML = buildHeroSlideHtml(entries[i], i);
        track.appendChild(slide);

        dotsHtml += "<button class='vtj-featured-slider-dot" + (i === 0 ? " active" : "") + "' data-index='" + i + "' aria-label='Go to slide " + (i + 1) + "'></button>";
      }

      container.innerHTML = "";
      container.appendChild(track);

      var dotsContainer = document.getElementById("vtj-featured-slider-dots");
      if (dotsContainer) dotsContainer.innerHTML = dotsHtml;

      initHeroSlider();
    }

    function buildHeroSlideHtml(entry, index) {
      var title = entry.title ? entry.title.$t : "";
      var safeTitle = escapeHtml(title);
      var postUrl   = getUrl(entry);
      var category   = getCategory(entry);
      var publishedDate  = formatDate(entry.published ? entry.published.$t : "");
      var description  = cleanSummary(entry.summary ? entry.summary.$t : "", 150);
      var highQualityImage   = getHighQualityImage(getFirstImgSrc(entry));
      var readingTime    = getReadingTime(entry) + " min read";
      var isFirstSlide = (index === 0);

      return "<a class='featured-image-link' href='" + postUrl + "' aria-label='Open " + safeTitle + "'>" +
        "<div class='featured-image-wrapper'>" +
          "<img class='featured-image' src='" + highQualityImage + "' alt='" + safeTitle + "' " +
          (isFirstSlide ? "loading='eager' fetchpriority='high'" : "loading='lazy' decoding='async'") +
          " width='800' height='450'/>" +
        "</div>" +
      "</a>" +
      "<div class='featured-content'>" +
        "<span class='featured-category'>" + category + "</span>" +
        "<h2 class='featured-title'><a href='" + postUrl + "'>" + safeTitle + "</a></h2>" +
        "<p class='featured-description'>" + description + "</p>" +
        "<div class='featured-meta'>" +
          "<span>" + publishedDate + "</span>" +
          "<span>" + readingTime + "</span>" +
        "</div>" +
        "<a class='featured-read-button' href='" + postUrl + "'>" +
          "Read Full Article <span aria-hidden='true'>\u2192</span>" +
        "</a>" +
      "</div>";
    }

    function initHeroSlider() {
      var prevBtn = document.getElementById("vtj-featured-slider-prev");
      var nextBtn = document.getElementById("vtj-featured-slider-next");
      var dotsContainer = document.getElementById("vtj-featured-slider-dots");
      var container = document.getElementById("vtj-featured-slider-container");
      var section = document.getElementById("vtj-featured-slider-section");

      if (prevBtn) prevBtn.addEventListener("click", function() { goToSlide(sliderCurrent - 1); });
      if (nextBtn) nextBtn.addEventListener("click", function() { goToSlide(sliderCurrent + 1); });

      if (dotsContainer) {
        dotsContainer.addEventListener("click", function(e) {
          var dot = e.target.closest(".vtj-featured-slider-dot");
          if (dot) {
            var idx = parseInt(dot.getAttribute("data-index"));
            if (!isNaN(idx)) goToSlide(idx);
          }
        });
      }

      if (container) {
        var touchStartX = 0;
        container.addEventListener("touchstart", function(e) {
          touchStartX = e.changedTouches[0].screenX;
        }, { passive: true });
        container.addEventListener("touchend", function(e) {
          var diff = touchStartX - e.changedTouches[0].screenX;
          if (Math.abs(diff) > 50) {
            goToSlide(diff > 0 ? sliderCurrent + 1 : sliderCurrent - 1);
          }
        }, { passive: true });
      }

      if (section) {
        section.addEventListener("keydown", function(e) {
          if (e.key === "ArrowLeft") { goToSlide(sliderCurrent - 1); e.preventDefault(); }
          if (e.key === "ArrowRight") { goToSlide(sliderCurrent + 1); e.preventDefault(); }
        });
      }

      if (container) {
        container.addEventListener("mouseenter", pauseSlider);
        container.addEventListener("mouseleave", resumeSlider);
      }

      if (section) {
        section.addEventListener("focusin", pauseSlider);
        section.addEventListener("focusout", function(e) {
          if (!section.contains(e.relatedTarget)) resumeSlider();
        });
      }

      document.addEventListener("visibilitychange", function() {
        if (document.hidden) pauseSlider(); else resumeSlider();
      });

      startSliderTimer();
    }

    function goToSlide(index) {
      var track = document.getElementById("vtj-featured-slider-track");
      if (!track) return;
      var slides = track.querySelectorAll(".featured-slide");
      if (slides.length === 0) return;

      if (index < 0) index = slides.length - 1;
      if (index >= slides.length) index = 0;

      slides.forEach(function(s, i) {
        var isActive = i === index;
        s.classList.toggle("active", isActive);
        s.setAttribute("aria-hidden", String(!isActive));
      });

      sliderCurrent = index;

      document.querySelectorAll(".vtj-featured-slider-dot").forEach(function(d, i) {
        d.classList.toggle("active", i === index);
      });

      resetSliderTimer();

      var nextIdx = index + 1 >= slides.length ? 0 : index + 1;
      var nextSlide = slides[nextIdx];
      if (nextSlide) {
        var nextImg = nextSlide.querySelector(".featured-image");
        if (nextImg) {
          var src = nextImg.getAttribute("src");
          if (src) { var p = new Image(); p.src = src; }
        }
      }
    }

    function startSliderTimer() {
      stopSliderTimer();
      if (sliderIsPaused) return;
      sliderTimer = setInterval(function() {
        if (!sliderIsPaused) goToSlide(sliderCurrent + 1);
      }, sliderInterval);
      startProgressBar();
    }

    function stopSliderTimer() {
      if (sliderTimer) { clearInterval(sliderTimer); sliderTimer = null; }
      stopProgressBar();
    }

    function resetSliderTimer() {
      stopSliderTimer();
      if (!sliderIsPaused) startSliderTimer();
    }

    function pauseSlider() {
      sliderIsPaused = true;
      stopSliderTimer();
    }

    function resumeSlider() {
      sliderIsPaused = false;
      startSliderTimer();
    }

    function startProgressBar() {
      var bar = document.getElementById("vtj-featured-slider-progress-bar");
      if (!bar) return;
      bar.style.transition = "none";
      bar.style.width = "0%";
      bar.offsetHeight;
      bar.style.transition = "width " + sliderInterval + "ms linear";
      bar.style.width = "100%";
    }

    function stopProgressBar() {
      var bar = document.getElementById("vtj-featured-slider-progress-bar");
      if (!bar) return;
      bar.style.transition = "none";
      bar.style.width = "0%";
    }

    /* ---- Magazine Category Blocks ---- */
    var magazineCats = [
      { label: "AI Tools",          elId: "mag-ai-tools",       blockId: "mag-block-ai-tools" },
      { label: "Useful Websites",   elId: "mag-useful-websites", blockId: "mag-block-websites" },
      { label: "Apps",              elId: "mag-apps",            blockId: "mag-block-apps" },
      { label: "Software",          elId: "mag-software",        blockId: "mag-block-software" },
      { label: "Student Tech",      elId: "mag-student-tech",    blockId: "mag-block-student" },
      { label: "Productivity",      elId: "mag-productivity",    blockId: "mag-block-productivity" }
    ];

    function makeMagCallback(cat) {
      return function(data) {
        var blockEl = document.getElementById(cat.blockId);
        var innerEl = document.getElementById(cat.elId);
        if (!innerEl) return;
        if (!data.feed || !data.feed.entry || data.feed.entry.length === 0) {
          if (blockEl) blockEl.style.display = "none";
          return;
        }
        var entries = data.feed.entry;
        var large = entries[0];
        var smalls = [];
        for (var i = 1; 4 > i && entries.length > i; i++) smalls.push(entries[i]);

        var lt = large.title ? large.title.$t : "";
        var lu = getUrl(large);
        var lc = getCategory(large);
        var ld = formatDate(large.published ? large.published.$t : "");
        var limg = getThumb(large, 600);
        var lexcerpt = large.summary ? large.summary.$t.substring(0, 120) + "..." : "";

        var html = "<div class='mag-large-card'>" +
          "<div class='mag-large-img'><a href='" + lu + "'><img src='" + limg + "' alt='" + lt.replace(/\"/g, "'") + "' width='600' height='338' loading='lazy' decoding='async'/></a>" +
          "<span class='mag-large-badge'>" + lc + "</span></div>" +
          "<div class='mag-large-body'>" +
          "<span class='mag-large-cat'>" + lc + "</span>" +
          "<h3 class='mag-large-title'><a href='" + lu + "'>" + lt + "</a></h3>" +
          "<p class='mag-large-excerpt'>" + lexcerpt + "</p>" +
          "<div class='mag-large-meta'><span>" + ld + "</span><span class='mag-large-meta-dot'>·</span><span>" + calcReadTime(lexcerpt) + " min read</span></div>" +
          "</div></div>";

        var smallHtml = "<div class='mag-small-group'>";
        for (var j = 0; smalls.length > j; j++) {
          var s = smalls[j];
          var st = s.title ? s.title.$t : "";
          var su = getUrl(s);
          var sc = getCategory(s);
          var sd = formatDate(s.published ? s.published.$t : "");
          var simg = getThumb(s, 200);
          smallHtml += "<div class='mag-small-card'>" +
            "<div class='mag-small-img'><a href='" + su + "'><img src='" + simg + "' alt='" + st.replace(/\"/g, "'") + "' width='200' height='150' loading='lazy' decoding='async'/></a></div>" +
            "<div class='mag-small-body'><span class='mag-small-cat'>" + sc + "</span>" +
            "<p class='mag-small-title'><a href='" + su + "'>" + st + "</a></p>" +
            "<span class='mag-small-date'>" + sd + "</span></div></div>";
        }
        smallHtml += "</div>";

        innerEl.innerHTML = html + smallHtml;
      };
    }

    function loadMagazineBlocks() {
      var firstMag = document.querySelector('.mag-block, [id^="mag-block-"], .trending-section');
      var loaded = false;
      function fetchAll() {
        if (loaded) return;
        loaded = true;
        magazineCats.forEach(function(cat, idx) {
          var cbName = "tvhMag_" + cat.elId.replace(/-/g, "_");
          window[cbName] = makeMagCallback(cat);
          setTimeout(function(c, n) {
            return function() {
              var sc = document.createElement("script");
              sc.src = BLOG_URL + "feeds/posts/summary/-/ " + encodeURIComponent(c.label) + "?alt=json-in-script&max-results=4&callback=" + n;
              document.body.appendChild(sc);
            };
          }(cat, cbName), idx * 120);

          setTimeout(function() {
            var innerEl = document.getElementById(cat.elId);
            if (innerEl && innerEl.querySelector(".skel, .mag-skel")) {
              var blockEl = document.getElementById(cat.blockId);
              if (blockEl) blockEl.style.display = "none";
            }
          }, 5000);
        });
      }

      if (firstMag && 'IntersectionObserver' in window) {
        var obs = new IntersectionObserver(function(entries, observer) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting) {
              observer.disconnect();
              fetchAll();
            }
          });
        }, { rootMargin: '400px' });
        obs.observe(firstMag);
      } else {
        if ('requestIdleCallback' in window) {
          requestIdleCallback(fetchAll, { timeout: 3000 });
        } else {
          setTimeout(fetchAll, 1500);
        }
      }
    }

    /* ---- Numbered Pagination ---- */
    function buildPagination() {
      var pag = document.getElementById('vtj-pagination');
      if (!pag) return;
      if (!document.querySelector('.main-posts-area, .Blog, #Blog1')) return;
      var perPage = 8;
      var homeUrl = pag.getAttribute('data-home') || '/';
      if (homeUrl.indexOf('http') !== 0) homeUrl = window.location.protocol + '//' + window.location.host + homeUrl;
      window.vtjPagBuild = function(data) {
        var total = parseInt(data.feed.openSearch$totalResults.$t) || 0;
        var totalPages = Math.ceil(total / perPage);
        if (totalPages <= 1) { pag.innerHTML = ''; return; }
        var entries = data.feed.entry || [];
        var currentPage = 1;
        var url = window.location.href;
        var urlTs = null;
        var m = url.match(/updated-max=([^&]+)/);
        if (m) {
          urlTs = decodeURIComponent(m[1]).replace(/\+/g, ' ');
          for (var i = 0; i < entries.length; i++) {
            if (entries[i].published && entries[i].published.$t >= urlTs) {
              currentPage = Math.floor(i / perPage) + 2;
              break;
            }
          }
          if (currentPage > totalPages) currentPage = totalPages;
        }
        function pageUrl(pageNum) {
          if (pageNum <= 1) return homeUrl;
          var idx = (pageNum - 1) * perPage - 1;
          if (entries[idx] && entries[idx].published) {
            var ts = entries[idx].published.$t.replace(/\.\d+/, '').replace(/Z/, '');
            return '/search?updated-max=' + encodeURIComponent(ts) + '&max-results=' + perPage;
          }
          return null;
        }
        var win = 2;
        var startPage = Math.max(1, currentPage - win);
        var endPage = Math.min(totalPages, currentPage + win);
        if (currentPage - win < 1) endPage = Math.min(totalPages, endPage + (win - (currentPage - startPage)));
        if (currentPage + win > totalPages) startPage = Math.max(1, startPage - (win - (endPage - currentPage)));
        var html = '<nav aria-label="Pagination" class="pagination">';
        if (currentPage > 1) {
          var pu = pageUrl(currentPage - 1);
          html += '<a class="pagination-btn pagination-prev" href="' + (pu || homeUrl) + '">\u2190 Previous</a>';
        } else {
          html += '<span class="pagination-btn pagination-prev pagination-disabled">\u2190 Previous</span>';
        }
        if (startPage > 1) {
          html += '<a class="pagination-btn pagination-num" href="' + homeUrl + '">1</a>';
          if (startPage > 2) html += '<span class="pagination-ellipsis">\u2026</span>';
        }
        for (var p = startPage; p <= endPage; p++) {
          if (p === currentPage) {
            html += '<span class="pagination-btn pagination-num pagination-active">' + p + '</span>';
          } else {
            var pu = p === 1 ? homeUrl : pageUrl(p);
            if (pu) html += '<a class="pagination-btn pagination-num" href="' + pu + '">' + p + '</a>';
          }
        }
        if (endPage < totalPages) {
          if (endPage < totalPages - 1) html += '<span class="pagination-ellipsis">\u2026</span>';
          var pu = pageUrl(totalPages);
          if (pu) html += '<a class="pagination-btn pagination-num" href="' + pu + '">' + totalPages + '</a>';
        }
        if (currentPage < totalPages) {
          var pu = pageUrl(currentPage + 1);
          html += '<a class="pagination-btn pagination-next" href="' + (pu || homeUrl) + '">Next \u2192</a>';
        } else {
          html += '<span class="pagination-btn pagination-next pagination-disabled">Next \u2192</span>';
        }
        html += '</nav>';
        pag.innerHTML = html;
      };
      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=150&fields=entry(published),openSearch$totalResults&callback=vtjPagBuild";
      document.body.appendChild(s);
    }

    /* ---- Latest Articles (fetch exactly 10 posts via JSON feed) ---- */
    function loadLatestArticles() {
      var grid = document.querySelector('.content-area .posts-grid');
      if (!grid) return;
      // Configuration: exactly 10 posts
      var POST_COUNT = 10;
      function imgSrcset(url) {
        var s1 = url.replace(/\/s\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w400-h225-c-rw/').replace(/=s\d+.*$/, '=w400-h225-c-rw').replace(/=w\d+-h\d+.*$/, '=w400-h225-c-rw');
        var s2 = url.replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/').replace(/=s\d+.*$/, '=w800-h450-c-rw').replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw');
        return s1 + ' 400w, ' + s2 + ' 800w';
      }
      window.vtjLatestCb = function(data) {
        var entries = data.feed && data.feed.entry;
        if (!entries || entries.length === 0) return;
        var html = '';
        // Process exactly POST_COUNT posts (not all available)
        var maxPosts = Math.min(entries.length, POST_COUNT);
        for (var i = 0; i < maxPosts; i++) {
          var e = entries[i];
          var rawT = e.title ? e.title.$t : '';
          var safeT = escapeHtml(rawT);
          var u = getUrl(e);
          var d = formatDate(e.published ? e.published.$t : '');
          var c = getCategory(e);
          var img = getFirstImgSrc(e);
          var snippet = e.summary ? cleanSummary(e.summary.$t, 120) : '';
          var readTime = calcReadTime(snippet || rawT);
          var loadingAttr = i === 0 ? 'eager' : 'lazy';
          var srcsetAttr = imgSrcset(img);
          html += '<article class="post-card fade-in-ready">' +
            '<div class="post-card-thumb">' +
              '<a href="' + u + '" aria-label="Read ' + safeT + '">' +
                '<img src="' + img + '" alt="' + safeT + '" loading="' + loadingAttr + '" decoding="async" width="400" height="225" srcset="' + srcsetAttr + '" sizes="(max-width: 640px) 400px, (max-width: 1024px) 50vw, 400px"/>' +
              '</a>' +
              '<span class="post-card-category">' + c + '</span>' +
            '</div>' +
            '<div class="post-card-body">' +
              '<h3 class="post-card-title"><a href="' + u + '">' + safeT + '</a></h3>' +
              '<p class="post-card-excerpt">' + snippet + '</p>' +
              '<div class="post-card-footer">' +
                '<div class="post-card-meta">' +
                  '<svg viewBox="0 0 24 24"><path d="M9 11H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20a2 2 0 002 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z"/></svg>' +
                  d +
                  '<span class="post-card-meta-dot"/>' +
                  '<svg viewBox="0 0 24 24"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z"/></svg>' +
                  '<span class="post-read-time-val">' + readTime + ' min</span>' +
                '</div>' +
                '<a class="post-card-readmore" href="' + u + '">' +
                  'Read' +
                  '<svg viewBox="0 0 24 24"><path d="M12 4l-1.41 1.41L16.17 11H4v2h12.17l-5.58 5.59L12 20l8-8z"/></svg>' +
                '</a>' +
              '</div>' +
            '</div>' +
          '</article>';
        }
        grid.innerHTML = html;
        var newCards = grid.querySelectorAll('.fade-in-ready');
        if ('IntersectionObserver' in window) {
          var io2 = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
              if (entry.isIntersecting) {
                entry.target.classList.add('visible');
                io2.unobserve(entry.target);
              }
            });
          }, { threshold: 0.1 });
          newCards.forEach(function(el) { io2.observe(el); });
        } else {
          newCards.forEach(function(el) { el.classList.add('visible'); });
        }
      };
      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=" + POST_COUNT + "&callback=vtjLatestCb";
      document.body.appendChild(s);
    }

    /* ---- Init All ---- */
    loadHeroSlider();
    loadMagazineBlocks();
    loadLatestArticles();
    buildPagination();

    /* ---- Articles Page (alphabetical listing) ---- */
    function loadArticlesPage() {
      var wrap = document.getElementById('articles-page-wrap');
      if (!wrap) return;
      wrap.style.display = 'block';
      var grid = document.getElementById('articles-page-grid');
      if (!grid) return;
      var blog = document.querySelector('.main-posts-area, .Blog, #Blog1');
      if (blog) blog.style.display = 'none';

      window.vtjArticlesCb = function(data) {
        var entries = data.feed && data.feed.entry ? data.feed.entry : [];
        if (entries.length === 0) {
          grid.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:3rem 0">No articles found.</p>';
          return;
        }
        entries.sort(function(a, b) {
          var ta = (a.title && a.title.$t || '').toLowerCase();
          var tb = (b.title && b.title.$t || '').toLowerCase();
          if (ta < tb) return -1;
          if (ta > tb) return 1;
          return 0;
        });
        var html = '';
        for (var i = 0; i < entries.length; i++) {
          var e = entries[i];
          var rawT = e.title ? e.title.$t : '';
          var safeT = escapeHtml(rawT);
          var u = getUrl(e);
          var d = formatDate(e.published ? e.published.$t : '');
          var c = getCategory(e);
          var img = getFirstImgSrc(e);
          html += '<article class="post-card fade-in-ready visible">' +
            '<div class="post-card-thumb">' +
              '<a href="' + u + '" aria-label="Read ' + safeT + '">' +
                '<img src="' + img + '" alt="' + safeT + '" loading="lazy" decoding="async" width="400" height="225"/>' +
              '</a>' +
              '<span class="post-card-category">' + c + '</span>' +
            '</div>' +
            '<div class="post-card-body">' +
              '<h3 class="post-card-title"><a href="' + u + '">' + safeT + '</a></h3>' +
              '<div class="post-card-footer">' +
                '<div class="post-card-meta">' +
                  '<svg viewBox="0 0 24 24" style="width:12px;height:12px;fill:currentColor"><path d="M9 11H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20a2 2 0 002 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z"/></svg>' +
                  d +
                '</div>' +
              '</div>' +
            '</div>' +
          '</article>';
        }
        grid.innerHTML = html;
      };

      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=150&callback=vtjArticlesCb";
      document.body.appendChild(s);

      setTimeout(function() {
        if (grid.querySelector('.articles-page-skeleton')) {
          grid.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:3rem 0">Unable to load articles. Please try again later.</p>';
        }
      }, 6000);
    }

    /* ====================================================
       SINGLE POST FEATURES
    ==================================================== */
    function initSinglePost() {
      /* Author avatar - use header logo */
      var logoImg = document.getElementById('header-logo-img');
      if (logoImg) {
        var postAvatar = document.getElementById('post-author-avatar-img');
        if (postAvatar) { postAvatar.src = logoImg.src; postAvatar.style.display = ''; }
        var bioAvatar = document.getElementById('author-bio-avatar-img');
        if (bioAvatar) { bioAvatar.src = logoImg.src; bioAvatar.style.display = ''; }
      }

      /* Copy link */
      var copyBtn = document.getElementById("share-copy-btn");
      if (copyBtn) {
        copyBtn.addEventListener("click", function() {
          var url = copyBtn.getAttribute("data-url") || window.location.href;
          if (navigator.clipboard) {
            navigator.clipboard.writeText(url).then(function() { copyBtn.title = "Copied!"; setTimeout(function() { copyBtn.title = "Copy link"; }, 2000); });
          } else {
            var ta = document.createElement("textarea");
            ta.value = url;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand("copy");
            document.body.removeChild(ta);
          }
        });
      }

      /* Table of Contents */
      var tocRail = document.querySelector('.vtj-toc-rail');
      var tocList = document.getElementById('vtj-toc-list');
      var postContent = document.getElementById('post-content');
      if (tocRail && tocList && postContent) {
        var headings = postContent.querySelectorAll('h2, h3');
        if (headings.length > 0) {
          var tocHtml = '';
          var observerOptions = { root: null, rootMargin: '-100px 0px -70% 0px', threshold: 0 };
          var headingElements = [];

          var showH3 = headings.length <= 12;
          for (var i = 0; i < headings.length; i++) {
            var h = headings[i];
            var isH3 = h.tagName.toLowerCase() === 'h3';
            if (isH3 && !showH3) continue;

            if (!h.id) h.id = 'heading-' + i + '-' + Math.random().toString(36).substr(2, 5);
            var levelClass = isH3 ? 'level-h3' : 'level-h2';
            tocHtml += '<a href="#' + h.id + '" class="vtj-toc-link ' + levelClass + '" data-target="' + h.id + '">' + h.textContent + '</a>';
            headingElements.push(h);
          }
          tocList.innerHTML = tocHtml;

          /* Plain TOC hiding */
          var allLists = postContent.querySelectorAll('ul, ol');
          for (var j = 0; j < allLists.length; j++) {
            var listPrev = allLists[j].previousElementSibling;
            if (listPrev && (listPrev.tagName.toLowerCase() === 'h2' || listPrev.tagName.toLowerCase() === 'h3') && listPrev.textContent.toLowerCase().indexOf('table of contents') !== -1) {
              allLists[j].style.display = 'none';
              listPrev.style.display = 'none';
            }
          }

          var tocLinks = tocList.querySelectorAll('.vtj-toc-link');
          var observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
              if (entry.isIntersecting) {
                for (var k = 0; k < tocLinks.length; k++) {
                  tocLinks[k].classList.remove('active');
                  if (tocLinks[k].getAttribute('data-target') === entry.target.id) {
                    tocLinks[k].classList.add('active');
                  }
                }
              }
            });
          }, observerOptions);

          for (var idx = 0; idx < headingElements.length; idx++) {
            observer.observe(headingElements[idx]);
          }

          /* Smooth scroll offset */
          for (var l = 0; l < tocLinks.length; l++) {
            tocLinks[l].addEventListener('click', function(e) {
              e.preventDefault();
              var targetId = this.getAttribute('data-target');
              var targetEl = document.getElementById(targetId);
              if (targetEl) {
                var headerOffset = 90;
                var elementPosition = targetEl.getBoundingClientRect().top;
                var offsetPosition = elementPosition + window.pageYOffset - headerOffset;
                window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
                history.pushState(null, null, '#' + targetId);
              }
            });
          }
        } else {
          tocRail.style.display = 'none';
        }
      }

      /* Post table: safe horizontal scroll wrapping only (no row removal, no reordering, no thead/tbody changes) */
      var postContentEl = document.getElementById('post-content');

      if (postContentEl) {
        var postTables = postContentEl.querySelectorAll('table');

        for (var tableIndex = 0; tableIndex < postTables.length; tableIndex++) {
          var currentTable = postTables[tableIndex];

          if (
            !currentTable.parentElement ||
            !currentTable.parentElement.classList.contains('post-table-scroll')
          ) {
            var tableWrapper = document.createElement('div');
            tableWrapper.className = 'post-table-scroll';

            currentTable.parentNode.insertBefore(tableWrapper, currentTable);
            tableWrapper.appendChild(currentTable);
          }

          currentTable.classList.add('vtj-post-table');
        }
      }

      /* ========================================
         Related Posts Carousel - High Resolution Images
         Fixed: Uses same image method as Articles page (getFirstImgSrc)
         ======================================== */
      (function() {
        var relSection = document.getElementById("related-section");
        var relTrack = document.getElementById("related-track");
        if (!relSection || !relTrack) return;

        // ========== Configuration ==========
        var CAROUSEL_CONFIG = {
          postCount: 10,
          placeholderImage: 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=70'
        };

        // ========== High-Resolution Image Function (Same as Articles Page) ==========
        // This extracts first image from content and converts to s1200 for sharp quality
        function getHighResImage(entry) {
          var content = (entry.content && entry.content.$t) || '';
          if (content) {
            var cm = content.match(/<img[^>]+src=["']([^"']+)["']/i);
            if (cm && cm[1] && cm[1].indexOf('data:') !== 0) {
              return cm[1]
                .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
                .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
                .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
                .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
                .replace(/=s\d+.*$/, '=w800-h450-c-rw');
            }
          }
          if (entry.media$thumbnail && entry.media$thumbnail.url) {
            return entry.media$thumbnail.url
              .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
              .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
              .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
              .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
              .replace(/=s\d+.*$/, '=w800-h450-c-rw');
          }
          var summary = (entry.summary && entry.summary.$t) || '';
          if (summary) {
            var sm = summary.match(/<img[^>]+src=["']([^"']+)["']/i);
            if (sm && sm[1]) return sm[1];
          }
          return CAROUSEL_CONFIG.placeholderImage;
        }

        // ========== Srcset Generator (Same as Articles Page) ==========
        // Creates responsive srcset for different screen sizes
        function imgSrcset(url) {
          var s1 = url.replace(/\/s\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w400-h225-c-rw/').replace(/=s\d+.*$/, '=w400-h225-c-rw').replace(/=w\d+-h\d+.*$/, '=w400-h225-c-rw');
          var s2 = url.replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/').replace(/=s\d+.*$/, '=w800-h450-c-rw').replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw');
          return s1 + ' 400w, ' + s2 + ' 800w';
        }

        // ========== Get Post URL ==========
        function getPostUrl(entry) {
          if (!entry) return "#";
          if (entry.link) {
            for (var i = 0; i < entry.link.length; i++) {
              if (entry.link[i].rel === "alternate") return entry.link[i].href;
            }
          }
          return "#";
        }

        // ========== Get Current Post ID for Exclusion ==========
        function getCurrentPostId() {
          var path = window.location.pathname;
          var match = path.match(/\/(\d{4})\/(\d{2})\/([^/.]+)/);
          return match ? match[3] : path;
        }

        // ========== Shuffle Array (Randomization) ==========
        function shuffleArray(array) {
          var shuffled = array.slice();
          for (var i = shuffled.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1));
            var temp = shuffled[i];
            shuffled[i] = shuffled[j];
            shuffled[j] = temp;
          }
          return shuffled;
        }

        // ========== Main Callback ==========
        window.vtjCarouselCb = function(data) {
          // Hide section if no data
          if (!data || !data.feed || !data.feed.entry) {
            relSection.style.display = "none";
            return;
          }

          var entries = data.feed.entry;
          var currentPostId = getCurrentPostId();
          var validPosts = [];
          var seenUrls = {};

          // Filter valid posts (exclude current, remove duplicates)
          for (var i = 0; i < entries.length; i++) {
            var entry = entries[i];
            var url = getPostUrl(entry);
            if (url === "#" || !url) continue;
            if (seenUrls[url]) continue;
            if (currentPostId && url.indexOf(currentPostId) !== -1) continue;
            seenUrls[url] = true;
            validPosts.push(entry);
          }

          // Randomize and limit to configured count
          var randomizedPosts = shuffleArray(validPosts);
          var selectedPosts = randomizedPosts.slice(0, CAROUSEL_CONFIG.postCount);

          // Hide if fewer than 2 posts
          if (selectedPosts.length < 2) {
            relSection.style.display = "none";
            return;
          }

          // Build HTML with HIGH-RESOLUTION IMAGES
          var html = "";
          for (var j = 0; j < selectedPosts.length; j++) {
            var post = selectedPosts[j];
            var postUrl = getPostUrl(post);
            var postTitle = (post.title && post.title.$t) ? post.title.$t : "Untitled Post";

            // USE HIGH-RESOLUTION IMAGE FUNCTION (Same as Articles Page)
            var img = getHighResImage(post);
            var srcsetAttr = imgSrcset(img);

            var safeTitle = escapeHtml(postTitle);
            // Build card with srcset, sizes, width, height attributes
            html += "<div class='related-card'>";
            html += "<div class='related-card-img'>";
            html += "<a href='" + postUrl + "' aria-label='Open " + safeTitle + "'>";
            // HIGH-QUALITY IMAGE with srcset for responsive sizes
            html += "<img src='" + img + "' alt='" + safeTitle + "' loading='lazy' decoding='async' width='400' height='225' srcset='" + srcsetAttr + "' sizes='(max-width: 640px) 400px, 400px'/>";
            html += "</a>";
            html += "</div>";
            html += "<div class='related-card-body'>";
            html += "<p class='related-card-title'><a href='" + postUrl + "'>" + postTitle + "</a></p>";
            html += "</div>";
            html += "</div>";
          }

          // Duplicate for seamless infinite scroll
          relTrack.innerHTML = html + html;
          relTrack.parentNode.classList.remove("paused");
        };

        // ========== Load Posts ==========
        var blogUrl = document.body.getAttribute("data-url") || "/";
        if (blogUrl.indexOf("blogger.com") !== -1) blogUrl = "/";
        if (blogUrl.charAt(blogUrl.length - 1) !== "/") blogUrl += "/";

        var script = document.createElement("script");
        // Fetch more posts (50) to ensure we have enough after filtering
        script.src = blogUrl + "feeds/posts/summary?alt=json-in-script&max-results=50&callback=vtjCarouselCb";
        document.body.appendChild(script);

        // ========== Carousel Interactions ==========
        var carousel = document.getElementById("related-carousel");
        if (carousel) {
          // Pause on hover
          carousel.addEventListener("mouseenter", function() { this.classList.add("paused"); });
          carousel.addEventListener("mouseleave", function() { this.classList.remove("paused"); });

          // Touch/scroll support for mobile
          var touchStartX = 0, touchScrollLeft = 0, isTouching = false;
          carousel.addEventListener("touchstart", function(e) {
            if (e.touches.length === 1) {
              touchStartX = e.touches[0].clientX;
              touchScrollLeft = this.scrollLeft;
              isTouching = true;
              this.classList.add("paused");
            }
          }, { passive: true });

          carousel.addEventListener("touchmove", function(e) {
            if (isTouching && e.touches.length === 1) {
              this.scrollLeft = touchScrollLeft + (touchStartX - e.touches[0].clientX);
            }
          }, { passive: true });

          carousel.addEventListener("touchend", function() {
            isTouching = false;
            setTimeout(function() { carousel.classList.remove("paused"); }, 1000);
          }, { passive: true });
        }
      })();

      /* FAQ accordion - independent per section */
      var faqSections = document.querySelectorAll('.vtj-faq-section');

      for (var sectionIndex = 0; sectionIndex < faqSections.length; sectionIndex++) {
        (function (faqSection) {
          var faqQuestions = faqSection.querySelectorAll('.vtj-faq-question');

          for (var questionIndex = 0; questionIndex < faqQuestions.length; questionIndex++) {
            faqQuestions[questionIndex].addEventListener('click', function () {
              var clickedQuestion = this;
              var clickedItem = clickedQuestion.closest('.vtj-faq-item');
              var isAlreadyOpen = clickedItem.classList.contains('active');
              var allItems = faqSection.querySelectorAll('.vtj-faq-item');

              for (var itemIndex = 0; itemIndex < allItems.length; itemIndex++) {
                allItems[itemIndex].classList.remove('active');

                var itemQuestion =
                  allItems[itemIndex].querySelector('.vtj-faq-question');

                if (itemQuestion) {
                  itemQuestion.setAttribute('aria-expanded', 'false');
                }
              }

              if (!isAlreadyOpen) {
                clickedItem.classList.add('active');
                clickedQuestion.setAttribute('aria-expanded', 'true');
              }
            });
          }
        })(faqSections[sectionIndex]);
      }

      /* Initialize code blocks for single posts */
      initCodeBlocks();
    }

    /* ============================================================
       PREMIUM CODE BLOCKS SYSTEM - AUTOMATIC CONVERSION & COPY
    ============================================================ */
    function initCodeBlocks() {
      var postContainers = document.querySelectorAll('.post-content, #post-content, .post-body, .post-body-card');
      if (!postContainers || !postContainers.length) return;

      var copyIconSvg = '<svg viewBox="0 0 24 24"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg>';
      var checkIconSvg = '<svg viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>';
      var expandIconSvg = '<svg viewBox="0 0 24 24"><path d="M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z"/></svg>';
      var collapseIconSvg = '<svg viewBox="0 0 24 24"><path d="M12 8l-6 6 1.41 1.41L12 10.83l4.59 4.58L18 14z"/></svg>';

      function normalizeLang(lang) {
        if (!lang) return '';
        var l = lang.toLowerCase().trim().replace(/^language-|^lang-/, '');
        switch (l) {
          case 'js':
          case 'javascript':
            return 'JavaScript';
          case 'html':
          case 'htm':
          case 'xhtml':
          case 'xml':
            return 'HTML';
          case 'css':
            return 'CSS';
          case 'py':
          case 'python':
            return 'Python';
          case 'java':
            return 'Java';
          case 'sql':
            return 'SQL';
          case 'php':
            return 'PHP';
          case 'cpp':
          case 'c++':
            return 'C++';
          case 'cs':
          case 'csharp':
          case 'c#':
            return 'C#';
          case 'c':
            return 'C';
          case 'json':
            return 'JSON';
          case 'bash':
          case 'sh':
          case 'shell':
          case 'zsh':
            return 'Bash';
          case 'md':
          case 'markdown':
            return 'Markdown';
          case 'ts':
          case 'typescript':
            return 'TypeScript';
          case 'yaml':
          case 'yml':
            return 'YAML';
        }
        return '';
      }

      function detectLanguage(preEl, codeEl) {
        var classString = '';
        if (preEl && preEl.className) classString += ' ' + preEl.className;
        if (codeEl && codeEl.className) classString += ' ' + codeEl.className;

        var matches = classString.match(/(?:lang|language)-([a-z0-9+#-]+)/i) || classString.match(/\b(html|css|javascript|js|python|py|java|sql|php|cpp|c\+\+|csharp|cs|c|json|bash|sh|shell|xml|markdown|md|typescript|ts)\b/i);

        if (matches) {
          var found = normalizeLang(matches[1] || matches[0]);
          if (found) return found;
        }

        var text = (codeEl || preEl).textContent.trim();
        if (/^<!DOCTYPE/i.test(text) || /^<html/i.test(text) || /^<div/i.test(text)) return 'HTML';
        if (/^import\s+[\w{}*,\s]+\s+from/i.test(text) || /^const\s+|^let\s+|^var\s+/i.test(text) || /^function\s*\w*\s*\(/.test(text)) return 'JavaScript';
        if (/^def\s+\w+\s*\(|^import\s+\w+|^from\s+\w+\s+import/i.test(text)) return 'Python';
        if (/^public\s+class\s+|^import\s+java\./i.test(text)) return 'Java';
        if (/^SELECT\s+|^INSERT\s+INTO|^UPDATE\s+|^DELETE\s+FROM/i.test(text)) return 'SQL';
        if (/^<\?php/i.test(text)) return 'PHP';
        if (/^{\s*"|^\s*\[\s*{/i.test(text)) return 'JSON';

        return 'CODE';
      }

      for (var c = 0; c < postContainers.length; c++) {
        var container = postContainers[c];
        var preElements = container.querySelectorAll('pre');

        for (var i = 0; i < preElements.length; i++) {
          var pre = preElements[i];

          if (pre.getAttribute('data-vtj-code') === 'true' || pre.closest('.vtj-code-block')) {
            continue;
          }

          var codeChild = pre.querySelector('code');
          var langName = detectLanguage(pre, codeChild);

          var blockWrapper = document.createElement('div');
          blockWrapper.className = 'vtj-code-block';

          var header = document.createElement('div');
          header.className = 'vtj-code-header';

          var langSpan = document.createElement('span');
          langSpan.className = 'vtj-code-lang';
          langSpan.textContent = langName;

          var actionsDiv = document.createElement('div');
          actionsDiv.className = 'vtj-code-actions';

          var expandBtn = document.createElement('button');
          expandBtn.type = 'button';
          expandBtn.className = 'vtj-code-btn vtj-code-expand';
          expandBtn.setAttribute('aria-label', 'Expand code block');
          expandBtn.style.display = 'none';
          expandBtn.innerHTML = expandIconSvg + '<span>Expand</span>';

          var copyBtn = document.createElement('button');
          copyBtn.type = 'button';
          copyBtn.className = 'vtj-code-btn vtj-code-copy';
          copyBtn.setAttribute('aria-label', 'Copy code');
          copyBtn.innerHTML = copyIconSvg + '<span class="vtj-copy-text">Copy</span>';

          actionsDiv.appendChild(expandBtn);
          actionsDiv.appendChild(copyBtn);

          header.appendChild(langSpan);
          header.appendChild(actionsDiv);

          var codeWrapper = document.createElement('div');
          codeWrapper.className = 'vtj-code-wrapper';

          pre.setAttribute('data-vtj-code', 'true');

          pre.parentNode.insertBefore(blockWrapper, pre);
          codeWrapper.appendChild(pre);
          blockWrapper.appendChild(header);
          blockWrapper.appendChild(codeWrapper);

          // Copy Logic
          (function (targetPre, btn) {
            btn.addEventListener('click', function () {
              var codeElement = targetPre.querySelector('code') || targetPre;
              var codeToCopy = codeElement.textContent;

              function onSuccess() {
                btn.classList.add('is-copied');
                btn.innerHTML = checkIconSvg + '<span class="vtj-copy-text">Copied!</span>';
                setTimeout(function () {
                  btn.classList.remove('is-copied');
                  btn.innerHTML = copyIconSvg + '<span class="vtj-copy-text">Copy</span>';
                }, 2000);
              }

              if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(codeToCopy).then(onSuccess).catch(function () {
                  fallbackCopy(codeToCopy, onSuccess);
                });
              } else {
                fallbackCopy(codeToCopy, onSuccess);
              }
            });
          })(pre, copyBtn);

          function fallbackCopy(text, cb) {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.position = 'fixed';
            ta.style.left = '-9999px';
            ta.style.top = '0';
            document.body.appendChild(ta);
            ta.focus();
            ta.select();
            try {
              document.execCommand('copy');
              cb();
            } catch (err) {
              console.error('Copy failed:', err);
            }
            document.body.removeChild(ta);
          }

          // Expand / Collapse Logic
          (function (wrapper, expBtn) {
            setTimeout(function () {
              if (wrapper.scrollHeight > 305) {
                expBtn.style.display = 'inline-flex';
                expBtn.addEventListener('click', function () {
                  var isExpanded = wrapper.classList.contains('is-expanded');
                  if (isExpanded) {
                    wrapper.classList.remove('is-expanded');
                    expBtn.innerHTML = expandIconSvg + '<span>Expand</span>';
                    expBtn.setAttribute('aria-label', 'Expand code block');
                  } else {
                    wrapper.classList.add('is-expanded');
                    expBtn.innerHTML = collapseIconSvg + '<span>Collapse</span>';
                    expBtn.setAttribute('aria-label', 'Collapse code block');
                  }
                });
              }
            }, 100);
          })(codeWrapper, expandBtn);
        }
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCodeBlocks);
      } else {
        initCodeBlocks();
      }
    }
  })();
  //
